/* The curriculum, in English and Rioplatense Spanish. A command is an instrument; the assessed skill is a justified prediction. */
window.ENTRA_COURSE = (() => {
  // Every text is { en, es }; a plain string reads the same in both languages.
  const B = x => (typeof x === 'object' ? x : { en: x, es: x });
  const F = (title, text, rule) => ({ title: B(title), text: B(text), rule: B(rule) });
  const Q = (question, options, correct, explanation) => {
    // Stable question-derived placement avoids a repeating answer-position pattern.
    const position = [...(question.en ?? question)].reduce((hash, ch) => Math.imul(hash ^ ch.charCodeAt(0), 16777619) >>> 0, 2166136261) % 3;
    [options[correct], options[position]] = [options[position], options[correct]];
    return { question: B(question), options: options.map(B), correct: position, explanation: B(explanation) };
  };
  const S = (title, text, expected, command = '') => ({ title: B(title), text: B(text), expected: B(expected), command });
  const lessons = [];
  const units = [{ en: 'Learn with evidence', es: 'Aprender con evidencia' }, { en: 'Draw the trust boundaries', es: 'Dibujar los límites de confianza' }, { en: 'Follow a sign-in', es: 'Seguir un inicio de sesión' }, { en: 'Enforce the API contract', es: 'Hacer cumplir el contrato de la API' }, { en: 'Protect the data', es: 'Proteger los datos' }, { en: 'Operate the identity system', es: 'Operar el sistema de identidad' }, { en: 'Defend the design', es: 'Defender el diseño' }].map(B);
  const lab = (scenario, prediction, observation, limit) => [
    S({ en: 'Predict before sending', es: 'Predecí antes de mandar' }, prediction, { en: 'Write the expected decision and the component responsible for it.', es: 'Escribí la decisión esperada y el componente responsable de tomarla.' }),
    S({ en: 'Run and inspect', es: 'Ejecutá e inspeccioná' }, { en: 'With the local stack running, use this scenario from the extracted labs folder. It sends requests to the real Spring API. Read the result before consulting the implementation.', es: 'Con el stack local corriendo, usá este escenario desde la carpeta labs descomprimida. Manda pedidos a la API Spring real. Leé el resultado antes de consultar la implementación.' }, observation, 'node lab.mjs ' + scenario),
    S({ en: 'Find the enforcing line', es: 'Encontrá la línea que lo hace cumplir' }, { en: 'Read api/src/main/java/course/entra/SecurityConfig.java, Requests.java or database/init.sql. Find the line that accounts for the observed decision. Follow the request in the Angular application at http://localhost:18094 as well.', es: 'Leé api/src/main/java/course/entra/SecurityConfig.java, Requests.java o database/init.sql. Encontrá la línea que explica la decisión observada. Seguí también el pedido en la aplicación Angular, en http://localhost:18094.' }, { en: 'Name a validator, an authority check or a SQL predicate, and explain the input it trusts.', es: 'Nombrá un validador, una verificación de authority o un predicado SQL, y explicá en qué entrada confía.' }),
    S({ en: 'State what remains unproven', es: 'Decí qué queda sin probar' }, limit, { en: 'Record prediction, observation, explanation and limit. A passing assertion does not certify your explanation.', es: 'Anotá predicción, observación, explicación y límite. Una aserción que pasa no certifica tu explicación.' })
  ];
  const study = (title, task, evidence, alternative) => [
    S({ en: 'Predict the boundary', es: 'Predecí el límite' }, title, { en: 'Write a prediction before opening the tenant or reading the case.', es: 'Escribí una predicción antes de abrir el tenant o de leer el caso.' }),
    S({ en: 'Follow the tenant workbook', es: 'Seguí el recorrido del tenant' }, task, evidence),
    S({ en: 'Account-free case study', es: 'Caso de estudio sin cuenta' }, alternative, { en: 'Label this route CASE STUDY. It demonstrates reasoning, not an Entra execution.', es: 'Marcá este recorrido como CASO DE ESTUDIO. Demuestra razonamiento, no una ejecución en Entra.' }),
    S({ en: 'Explain the result', es: 'Explicá el resultado' }, { en: 'Draw the before and after. Mark what Entra decided, what Spring decided and what PostgreSQL could know. Keep raw tokens and personal data out of the notebook.', es: 'Dibujá el antes y el después. Marcá qué decidió Entra, qué decidió Spring y qué podía saber PostgreSQL. Dejá los tokens crudos y los datos personales fuera del cuaderno.' }, { en: 'State the observation route and one guarantee it cannot establish.', es: 'Indicá el recorrido de observación y una garantía que no puede establecer.' })
  ];
  function add(unit, slug, title, intro, visual, frames, experiment, quiz, steps, source, mode = 'local') {
    lessons.push({ id: lessons.length, unit, slug, title: B(title), intro: B(intro), visual, frames,
      experiment: B(experiment), quiz, lab: steps, source, mode });
  }

  add(0, 'before-you-start', { en: 'Before you start', es: 'Antes de empezar' }, { en: 'Learn to explain a decision all the way from the browser to a row.', es: 'Aprendé a explicar una decisión de punta a punta, desde el navegador hasta una fila.' }, 'boundaries', [
    F({ en: 'One application, one recurring question', es: 'Una aplicación, una pregunta que vuelve' }, { en: 'A research team buys equipment. Alice submits a purchase request. Bob submits another. An approver may approve somebody else\'s pending request in the same tenant. Angular presents the interface, Spring enforces the rules, PostgreSQL stores the records, and Microsoft Entra ID supplies identity and access tokens. Our recurring question is: who may do what to which record, and which component proves it?', es: 'Un equipo de investigación compra equipos. Alice carga una solicitud de compra. Bob carga otra. Un aprobador puede aprobar la solicitud pendiente de otra persona en el mismo tenant. Angular presenta la interfaz, Spring hace cumplir las reglas, PostgreSQL guarda los registros y Microsoft Entra ID aporta la identidad y los access tokens. Nuestra pregunta de siempre es: ¿quién puede hacer qué sobre qué registro, y qué componente lo prueba?' }, { en: 'A successful sign-in is the start of the investigation.', es: 'Un inicio de sesión exitoso es el comienzo de la investigación.' }),
    F({ en: 'Three grades of evidence', es: 'Tres niveles de evidencia' }, { en: 'The diagrams are deterministic models. The local kit runs a real Angular client, Spring resource server and PostgreSQL database with a deliberately simple test-token dispenser. It does not authenticate people or implement Entra. The tenant workbook switches to actual Entra registrations and users. Keep a model prediction, a local assertion and a tenant observation distinct in your notes.', es: 'Los diagramas son modelos deterministas. El kit local ejecuta un cliente Angular, un resource server de Spring y una base de datos PostgreSQL reales, con un emisor de tokens de prueba deliberadamente simple. No autentica personas ni implementa Entra. El recorrido del tenant pasa a registros y usuarios reales de Entra. En tus notas, mantené separadas la predicción de un modelo, una aserción local y una observación en el tenant.' }, { en: 'Never promote fixture evidence into an Entra guarantee.', es: 'Nunca conviertas evidencia del fixture en una garantía de Entra.' }),
    F({ en: 'Prepare, then investigate', es: 'Prepará, después investigá' }, { en: 'You need basic HTTP and JSON knowledge. Read the overview first if identity vocabulary is new. The static course works offline. For the kit use Node.js 24 and Docker with Compose v2; the first build downloads dependencies. Angular is compiled locally. No paid Entra feature is required for the core tenant exercise, but account permissions and organizational policy can restrict registration and consent.', es: 'Necesitás conocimientos básicos de HTTP y JSON. Si el vocabulario de identidad es nuevo para vos, leé primero la orientación. El curso estático funciona sin conexión. Para el kit usá Node.js 24 y Docker con Compose v2; el primer build descarga dependencias. Angular se compila en tu máquina. El ejercicio central del tenant no necesita ninguna función paga de Entra, pero los permisos de la cuenta y la política de la organización pueden restringir el registro y el consentimiento.' }, { en: 'The checkpoint assesses the reason, not command recall.', es: 'El control evalúa el porqué, no que recuerdes comandos.' })
  ], { en: 'Select a failed boundary. Which component should refuse the request?', es: 'Elegí un límite que falla. ¿Qué componente debería rechazar el pedido?' }, [
    Q({ en: 'A local test rejects a forged JWT. What did it establish?', es: 'Una prueba local rechaza un JWT falsificado. ¿Qué estableció?' }, [{ en: 'The tenant requires MFA', es: 'El tenant exige MFA' }, { en: 'Spring rejected this fixture signature', es: 'Spring rechazó esta firma del fixture' }, { en: 'The browser cannot suffer XSS', es: 'El navegador no puede sufrir XSS' }], 1, { en: 'The test exercises the configured API validator. It says nothing about tenant sign-in policy or browser compromise.', es: 'La prueba ejercita el validador configurado de la API. No dice nada de la política de inicio de sesión del tenant ni de un navegador comprometido.' }),
    Q({ en: 'What should your notebook contain?', es: '¿Qué tendría que tener tu cuaderno?' }, [{ en: 'Prediction, observation, explanation and limit', es: 'Predicción, observación, explicación y límite' }, { en: 'Only a copied command', es: 'Solo un comando copiado' }, { en: 'Only a screenshot of PASS', es: 'Solo una captura del PASS' }], 0, { en: 'The useful evidence connects a prediction to an observed decision and states what remains untested.', es: 'La evidencia útil conecta una predicción con una decisión observada y dice qué queda sin probar.' }),
    Q({ en: 'Can you study without an Entra tenant?', es: '¿Se puede estudiar sin un tenant de Entra?' }, [{ en: 'Only the glossary', es: 'Solo el glosario' }, { en: 'Yes, including proof of tenant consent', es: 'Sí, incluida la prueba del consentimiento en el tenant' }, { en: 'Yes, with local tests and explicitly labeled case studies', es: 'Sí, con pruebas locales y casos de estudio indicados como tales' }], 2, { en: 'The case studies preserve the reasoning exercise, but cannot prove an online policy was enforced.', es: 'Los casos de estudio conservan el ejercicio de razonamiento, pero no pueden probar que se aplicó una política en línea.' })
  ], [
    S({ en: 'Read the lab contract', es: 'Leé el contrato del lab' }, { en: 'Extract downloads/entra-labs.zip. Open labs/README.md. Check the port list and the distinction between fixture and Entra modes.', es: 'Descomprimí downloads/entra-labs.zip. Abrí labs/README.md. Revisá la lista de puertos y la diferencia entre los modos fixture y Entra.' }, { en: 'The kit includes the Angular source, Spring source, SQL, tenant workbook and capstone rubric.', es: 'El kit trae el código de Angular, el de Spring, el SQL, el recorrido del tenant y la rúbrica del trabajo final.' }),
    S({ en: 'Prepare the configuration', es: 'Prepará la configuración' }, { en: 'Open a terminal in labs. This copies a public example configuration only if none exists. It never overwrites tenant settings.', es: 'Abrí una terminal en labs. Esto copia una configuración pública de ejemplo solo si no hay ninguna. Nunca pisa la configuración del tenant.' }, { en: 'Frontend configuration present, Node version and the next startup steps.', es: 'La configuración del frontend presente, la versión de Node y los próximos pasos para arrancar.' }, 'node lab.mjs setup'),
    S({ en: 'Start the API and database', es: 'Arrancá la API y la base de datos' }, { en: 'The project is named prumathe-entra. Only its API and fixture issuer publish loopback ports. The first build downloads images and Java dependencies; later builds reuse the cache.', es: 'El proyecto se llama prumathe-entra. Solo su API y el emisor del fixture publican puertos en loopback. El primer build descarga imágenes y dependencias de Java; los siguientes reutilizan la caché.' }, { en: 'The db, issuer and api services start. Read /health if startup is still in progress.', es: 'Arrancan los servicios db, issuer y api. Leé /health si el arranque todavía está en curso.' }, 'docker compose up -d --build'),
    S({ en: 'Start the Angular client', es: 'Arrancá el cliente Angular' }, { en: 'In the frontend subfolder run npm ci, then npm start. Open http://localhost:18094. Keep that terminal running. Run later lab commands from labs.', es: 'En la subcarpeta frontend ejecutá npm ci y después npm start. Abrí http://localhost:18094. Dejá esa terminal corriendo. Los comandos de los labs siguientes ejecutalos desde labs.' }, { en: 'Local fixture mode, Alice, and a Ready message. No person was signed in.', es: 'Modo fixture local, Alice y un mensaje Ready. No se inició la sesión de ninguna persona.' }),
    S({ en: 'Make a baseline observation', es: 'Hacé una observación de base' }, { en: 'Run the boundary scenario from labs. Predict what changes when a token is added.', es: 'Ejecutá el escenario boundary desde labs. Predecí qué cambia cuando se agrega un token.' }, { en: 'No token gives 401; Alice reading request 41 gives 200.', es: 'Sin token da 401; Alice leyendo la solicitud 41 da 200.' }, 'node lab.mjs boundary')
  ], 'overview');

  add(1, 'four-boundaries', { en: 'Four components, four responsibilities', es: 'Cuatro componentes, cuatro responsabilidades' }, { en: 'A request crosses boundaries; trust does not travel automatically.', es: 'Un pedido cruza límites; la confianza no viaja sola.' }, 'boundaries', [
    F({ en: 'The browser is controlled by its user', es: 'El navegador lo controla su usuario' }, { en: 'Angular can improve navigation, hide unavailable actions and display an account name. A user can also inspect its bundle, change its JavaScript or send an HTTP request without it. The browser is a client of the API, not a protected extension of the API. Anything necessary for permission enforcement must survive a caller bypassing the interface.', es: 'Angular puede mejorar la navegación, ocultar las acciones que no están disponibles y mostrar el nombre de una cuenta. Un usuario también puede inspeccionar su bundle, cambiar su JavaScript o mandar un pedido HTTP sin él. El navegador es un cliente de la API, no una extensión protegida de la API. Todo lo que haga falta para hacer cumplir los permisos tiene que resistir que quien llama saltee la interfaz.' }, { en: 'A route guard is a usability control, not an API boundary.', es: 'Un route guard es un control de usabilidad, no un límite de la API.' }),
    F({ en: 'The API owns the business decision', es: 'La decisión de negocio es de la API' }, { en: 'Entra issues a token for a resource under its identity and consent policies. Spring validates that token and then applies the application\'s rules. Knowing that Alice authenticated does not tell Entra whether purchase request 42 is Bob\'s, whether it is pending, or whether this purchase exceeds a limit. Those facts belong to the application.', es: 'Entra emite un token para un recurso según sus políticas de identidad y de consentimiento. Spring valida ese token y después aplica las reglas de la aplicación. Saber que Alice se autenticó no le dice a Entra si la solicitud de compra 42 es de Bob, si está pendiente o si esta compra supera un límite. Esos hechos son de la aplicación.' }, { en: 'Identity evidence is an input to authorization, not its complete answer.', es: 'La evidencia de identidad es una entrada de la autorización, no su respuesta completa.' }),
    F({ en: 'The database sees a connection', es: 'La base de datos ve una conexión' }, { en: 'PostgreSQL authenticates the application\'s database role. It does not automatically know which browser user caused a query. Our API carries validated tenant and subject context into a transaction and also constrains the SQL. These are separate connections with separate credentials. A token sent to the API is not forwarded as a PostgreSQL password.', es: 'PostgreSQL autentica el rol de base de datos de la aplicación. No sabe por sí solo qué usuario del navegador causó una consulta. Nuestra API lleva el contexto validado de tenant y de sujeto a una transacción, y además restringe el SQL. Son conexiones distintas, con credenciales distintas. Un token enviado a la API no se reenvía como contraseña de PostgreSQL.' }, { en: 'Name the principal at every hop.', es: 'Nombrá el principal en cada salto.' })
  ], { en: 'Switch between sign-in, API and row failures. Notice where the request stops.', es: 'Alterná entre fallas de inicio de sesión, de la API y de filas. Fijate dónde se frena el pedido.' }, [
    Q({ en: 'An Angular button is hidden. Can the API assume the operation is protected?', es: 'Un botón de Angular está oculto. ¿La API puede suponer que la operación está protegida?' }, [{ en: 'No, callers can bypass the UI', es: 'No, quien llama puede saltear la UI' }, { en: 'Yes, if the guard checked a role', es: 'Sí, si el guard verificó un rol' }, { en: 'Yes, if the bundle was minified', es: 'Sí, si el bundle se minificó' }], 0, { en: 'The API must independently enforce the operation for every request.', es: 'La API tiene que hacer cumplir la operación por su cuenta, en cada pedido.' }),
    Q({ en: 'Which component knows whether request 42 is still pending?', es: '¿Qué componente sabe si la solicitud 42 sigue pendiente?' }, [{ en: 'The SPA registration', es: 'El registro de la SPA' }, { en: 'The token signature', es: 'La firma del token' }, { en: 'The application and its database', es: 'La aplicación y su base de datos' }], 2, { en: 'Business state is read and changed inside the application boundary.', es: 'El estado del negocio se lee y se cambia dentro del límite de la aplicación.' }),
    Q({ en: 'Which principal normally opens the database connection here?', es: '¿Qué principal abre normalmente la conexión a la base de datos acá?' }, [{ en: 'The browser user directly', es: 'El usuario del navegador, directamente' }, { en: 'The API database role', es: 'El rol de base de datos de la API' }, { en: 'The SPA client ID', es: 'El client ID de la SPA' }], 1, { en: 'The JDBC connection authenticates app_runtime. End-user context must be handled separately.', es: 'La conexión JDBC autentica a app_runtime. El contexto del usuario final se tiene que manejar aparte.' })
  ], lab('boundary', { en: 'Will removing the token affect the static page, the API, or both?', es: '¿Quitar el token afecta a la página estática, a la API o a las dos?' }, { en: '401 without a token, 200 for Alice reading her request.', es: '401 sin token, 200 para Alice leyendo su solicitud.' }, { en: 'The fixture proves a resource-server boundary. It does not prove how Entra authenticated Alice.', es: 'El fixture prueba un límite de resource server. No prueba cómo Entra autenticó a Alice.' }), 'architecture');

  add(1, 'authentication-and-authorization', { en: 'Authentication and authorization', es: 'Autenticación y autorización' }, { en: 'Who is represented? What is this caller allowed to do?', es: '¿A quién se representa? ¿Qué puede hacer quien llama?' }, 'policy', [
    F({ en: 'Two questions with different evidence', es: 'Dos preguntas con evidencia distinta' }, { en: 'Authentication establishes an identity according to a mechanism and its trust assumptions. Authorization evaluates whether an action is permitted. At sign-in, Entra authenticates the person. At the API, Spring authenticates the bearer request using a validated token. Neither operation proves the human is physically present for every subsequent HTTP request.', es: 'La autenticación establece una identidad según un mecanismo y sus supuestos de confianza. La autorización evalúa si una acción está permitida. Al iniciar sesión, Entra autentica a la persona. En la API, Spring autentica el pedido bearer con un token validado. Ninguna de las dos operaciones prueba que la persona esté físicamente presente en cada pedido HTTP que sigue.' }, { en: 'A bearer request presents evidence; possession matters.', es: 'Un pedido bearer presenta evidencia: lo que cuenta es tenerla.' }),
    F({ en: 'Policy is a conjunction', es: 'La política es una conjunción' }, { en: 'Our approval endpoint requires an access token for this API, a delegated Requests.Approve scope, the user app role Approver, the correct tenant, another person\'s request and a pending status. Each requirement contributes a distinct fact. Removing any necessary fact should deny the operation, even if every other condition is true.', es: 'Nuestro endpoint de aprobación exige un access token para esta API, el scope delegado Requests.Approve, el app role de usuario Approver, el tenant correcto, una solicitud de otra persona y un estado pendiente. Cada requisito aporta un hecho distinto. Si falta cualquier hecho necesario, la operación se tiene que rechazar, aunque todas las demás condiciones se cumplan.' }, { en: 'Write the policy as AND before writing annotations.', es: 'Escribí la política como AND antes de escribir anotaciones.' }),
    F({ en: 'Identity is necessary but insufficient', es: 'La identidad es necesaria pero no alcanza' }, { en: 'Alice can be authenticated and still lack a role. An approver can have a role and still be forbidden to approve their own request. A correct identity can be associated with a record in another tenant. Denial is often the correct operation of a secure system, not a sign-in defect to fix by broadening permissions.', es: 'Alice puede estar autenticada y aun así no tener un rol. Un aprobador puede tener el rol y aun así no poder aprobar su propia solicitud. Una identidad correcta puede estar asociada a un registro de otro tenant. Muchas veces el rechazo es el funcionamiento correcto de un sistema seguro, no una falla de inicio de sesión que haya que arreglar ampliando permisos.' }, { en: 'A denial must be explained at the boundary that made it.', es: 'Un rechazo se tiene que explicar en el límite que lo produjo.' })
  ], { en: 'Toggle the scope, role or ownership condition. Can one successful check compensate for another failure?', es: 'Alterná la condición de scope, de rol o de propiedad. ¿Una verificación exitosa puede compensar otra que falla?' }, [
    Q({ en: 'Alice signs in successfully but cannot approve. Is that necessarily a bug?', es: 'Alice inicia sesión bien pero no puede aprobar. ¿Es necesariamente un bug?' }, [{ en: 'Yes, sign-in grants all app actions', es: 'Sí, iniciar sesión habilita todas las acciones de la app' }, { en: 'Yes, because the token is signed', es: 'Sí, porque el token está firmado' }, { en: 'No, authentication can succeed while authorization denies', es: 'No, la autenticación puede salir bien mientras la autorización rechaza' }], 2, { en: 'The operation has requirements that are independent of sign-in.', es: 'La operación tiene requisitos que no dependen del inicio de sesión.' }),
    Q({ en: 'Which policy matches the sample?', es: '¿Qué política coincide con el ejemplo?' }, [{ en: 'Scope AND role AND resource rules', es: 'Scope AND rol AND reglas del recurso' }, { en: 'Scope OR role', es: 'Scope OR rol' }, { en: 'Any valid token', es: 'Cualquier token válido' }], 0, { en: 'The checks represent different constraints; they are not substitutes.', es: 'Las verificaciones representan restricciones distintas; no se reemplazan entre sí.' }),
    Q({ en: 'What does a bearer token prove about presence?', es: '¿Qué prueba un bearer token sobre la presencia?' }, [{ en: 'The person is using this keyboard', es: 'La persona está usando este teclado' }, { en: 'The caller possesses accepted token evidence', es: 'Quien llama tiene evidencia de token aceptada' }, { en: 'The browser cannot copy it', es: 'El navegador no lo puede copiar' }], 1, { en: 'Bearer tokens can be replayed by anyone who obtains them, within the accepting API\'s checks.', es: 'Cualquiera que consiga un bearer token lo puede volver a usar, dentro de las verificaciones de la API que lo acepta.' })
  ], lab('matrix', { en: 'Predict four statuses: anonymous read, own read, unprivileged approval, somebody else\'s read.', es: 'Predecí cuatro códigos de estado: lectura anónima, lectura propia, aprobación sin privilegios y lectura de una solicitud ajena.' }, { en: '401, 200, 403 and 404, respectively.', es: '401, 200, 403 y 404, en ese orden.' }, { en: 'HTTP status explains the contract, not every internal reason. This API uses 404 to avoid revealing protected row existence.', es: 'El código de estado HTTP explica el contrato, no cada motivo interno. Esta API usa 404 para no revelar que existe una fila protegida.' }), 'claims');

  add(1, 'tenant-app-principal', { en: 'Tenant, application, service principal', es: 'Tenant, aplicación, service principal' }, { en: 'Separate the application definition from its presence in a directory.', es: 'Separá la definición de la aplicación de su presencia en un directorio.' }, 'registrations', [
    F({ en: 'A directory boundary', es: 'Un límite de directorio' }, { en: 'A workforce tenant contains identities and configuration for an organization. The tenant ID identifies that directory. Our baseline accepts one tenant with an explicit issuer. Replacing that issuer with common is not a safe shortcut to a multitenant application: onboarding, issuer validation and data partitioning would all need a design.', es: 'Un tenant workforce contiene las identidades y la configuración de una organización. El tenant ID identifica ese directorio. Nuestra configuración base acepta un solo tenant, con un issuer explícito. Reemplazar ese issuer por common no es un atajo seguro hacia una aplicación multitenant: el alta de organizaciones, la validación del issuer y la partición de los datos necesitarían un diseño.' }, { en: 'A tenant is part of the trust boundary, not just a login hint.', es: 'Un tenant es parte del límite de confianza, no solo una pista para el inicio de sesión.' }),
    F({ en: 'Definition and local instance', es: 'Definición e instancia local' }, { en: 'An app registration creates an application object in its home directory. A service principal represents the application in a tenant; Enterprise applications is the administrative view used for many of those tenant-level settings. The application client ID identifies the app, while object IDs identify directory objects. Copying the wrong ID can create a configuration that looks plausible but names the wrong thing.', es: 'Un app registration crea un objeto de aplicación en su directorio de origen. Un service principal representa la aplicación en un tenant; Enterprise applications (Aplicaciones empresariales) es la vista de administración que se usa para muchas de esas configuraciones a nivel de tenant. El client ID de la aplicación identifica la app, mientras que los object IDs identifican objetos del directorio. Copiar el ID equivocado puede crear una configuración que parece razonable pero nombra otra cosa.' }, { en: 'Application ID and object ID are different identifiers.', es: 'Application ID y object ID son identificadores distintos.' }),
    F({ en: 'A stable application identity key', es: 'Una clave de identidad estable para la aplicación' }, { en: 'A person\'s display name or email can change and can be reused. The API uses the validated pair tid and oid as its tenant-local identity key. Guest identities need attention: the object represented in the resource tenant is not interchangeable with an object from the person\'s home tenant. Define deprovisioning and data ownership explicitly.', es: 'El nombre visible o el email de una persona pueden cambiar y se pueden reutilizar. La API usa el par validado tid y oid como su clave de identidad local al tenant. Las identidades de invitados requieren atención: el objeto que las representa en el tenant del recurso no es intercambiable con un objeto del tenant de origen de la persona. Definí de forma explícita la baja de usuarios y la propiedad de los datos.' }, { en: 'Readable names are labels; authorization uses validated identifiers.', es: 'Los nombres legibles son etiquetas; la autorización usa identificadores validados.' })
  ], { en: 'Select client, API or tenant. Which identifier names the resource receiving the token?', es: 'Elegí cliente, API o tenant. ¿Qué identificador nombra al recurso que recibe el token?' }, [
    Q({ en: 'Which pair identifies the user in this course\'s data model?', es: '¿Qué par identifica al usuario en el modelo de datos de este curso?' }, [{ en: 'Display name and email', es: 'Nombre visible y email' }, { en: 'Validated tid and oid', es: 'tid y oid validados' }, { en: 'SPA client ID and email', es: 'Client ID de la SPA y email' }], 1, { en: 'The directory and object IDs are the explicit identity key; labels are not stable authorization keys.', es: 'Los IDs de directorio y de objeto son la clave de identidad explícita; las etiquetas no son claves de autorización estables.' }),
    Q({ en: 'A service principal is best understood as what?', es: '¿Cómo se entiende mejor un service principal?' }, [{ en: 'An application\'s instance in a tenant', es: 'La instancia de una aplicación en un tenant' }, { en: 'The Java process ID', es: 'El ID del proceso de Java' }, { en: 'Every user who signs in', es: 'Cada usuario que inicia sesión' }], 0, { en: 'It represents the application in that directory and carries tenant-local relationships.', es: 'Representa la aplicación en ese directorio y lleva las relaciones locales del tenant.' }),
    Q({ en: 'Does changing the authority to common finish multitenant support?', es: '¿Cambiar la authority a common completa el soporte multitenant?' }, [{ en: 'Yes, because all users can sign in', es: 'Sí, porque todos los usuarios pueden iniciar sesión' }, { en: 'Yes, if CORS is enabled', es: 'Sí, si CORS está habilitado' }, { en: 'No, trust and data isolation still need explicit rules', es: 'No, la confianza y el aislamiento de los datos siguen necesitando reglas explícitas' }], 2, { en: 'Accepted issuers and tenant onboarding must align with row ownership and operational policy.', es: 'Los issuers aceptados y el alta de tenants tienen que estar alineados con la propiedad de las filas y la política operativa.' })
  ], study({ en: 'Which IDs would change if another organization adopted the application?', es: '¿Qué IDs cambiarían si otra organización adoptara la aplicación?' }, { en: 'Inspect the Overview pages of the API and SPA registrations and their Enterprise application entries. Record identifier labels only. Use TENANT.md in the lab kit. Use a practice tenant and invented purchase requests.', es: 'Inspeccioná las páginas Overview (Información general) de los registros de la API y de la SPA, y sus entradas en Enterprise applications. Anotá solo las etiquetas de los identificadores. Usá TENANT.md del kit. Usá un tenant de práctica y solicitudes de compra inventadas.' }, { en: 'Two application client IDs and two distinct directory object identities, with the same chosen tenant ID.', es: 'Dos client IDs de aplicación y dos identidades de objeto del directorio distintas, con el mismo tenant ID elegido.' }, { en: 'A ticket contains a client ID where an API audience is expected and a service-principal object ID where a client ID is expected. Draw the objects and diagnose the mismatch before changing anything.', es: 'Un ticket tiene un client ID donde se espera la audiencia de una API, y el object ID de un service principal donde se espera un client ID. Dibujá los objetos y diagnosticá la discrepancia antes de cambiar nada.' }), 'objects', 'tenant');

  add(1, 'two-registrations', { en: 'Two registrations, one application experience', es: 'Dos registros, una experiencia de aplicación' }, { en: 'Angular is the client. Spring is the resource.', es: 'Angular es el cliente. Spring es el recurso.' }, 'registrations', [
    F({ en: 'Register the recipient separately', es: 'Registrá al destinatario por separado' }, { en: 'The API registration defines the resource: its application ID URI, delegated scopes and the user app role Approver. The SPA registration defines the public client and its allowed redirect URI. Keeping them separate makes the token\'s recipient visible. Requesting api://API_CLIENT_ID/Requests.Read expresses both a resource and a delegated permission.', es: 'El registro de la API define el recurso: su Application ID URI, los scopes delegados y el app role de usuario Approver. El registro de la SPA define el cliente público y su redirect URI permitida. Mantenerlos separados deja a la vista el destinatario del token. Pedir api://API_CLIENT_ID/Requests.Read expresa a la vez un recurso y un permiso delegado.' }, { en: 'The access token audience names the API, not the interface.', es: 'La audiencia del access token nombra a la API, no a la interfaz.' }),
    F({ en: 'Public means unable to keep a secret', es: 'Público quiere decir que no puede guardar un secreto' }, { en: 'The SPA client ID and tenant ID are public configuration. A client secret embedded in JavaScript would be readable by every visitor; it would not turn Angular into a confidential client. Register a Single-page application redirect path. The sample uses http://localhost:18094/redirect for local development and a dedicated MSAL redirect bridge.', es: 'El client ID de la SPA y el tenant ID son configuración pública. Un client secret incrustado en JavaScript lo podría leer cualquier visitante; no convertiría a Angular en un cliente confidencial. Registrá una ruta de redirect de tipo Single-page application (Aplicación de página única). El ejemplo usa http://localhost:18094/redirect para el desarrollo local y un bridge de redirect de MSAL dedicado.' }, { en: 'A browser application must not rely on a stored client secret.', es: 'Una aplicación de navegador no tiene que depender de un client secret guardado.' }),
    F({ en: 'Make token expectations explicit', es: 'Hacé explícito qué se espera del token' }, { en: 'Configure the API to request v2 access tokens with requestedAccessTokenVersion set to 2. The API validates the v2 issuer, its own client ID as audience, tenant, delegated scopes and allowed client. The version of the authorization endpoint alone does not choose the resource\'s access-token format. A registration is configuration, not deployed API code.', es: 'Configurá la API para que pida access tokens v2, con requestedAccessTokenVersion en 2. La API valida el issuer v2, su propio client ID como audiencia, el tenant, los scopes delegados y el cliente permitido. La versión del authorization endpoint, por sí sola, no elige el formato del access token del recurso. Un registro es configuración, no código de la API desplegado.' }, { en: 'A registration and a resource-server validator must agree.', es: 'Un registro y el validador de un resource server tienen que coincidir.' })
  ], { en: 'Swap the ID token recipient and API recipient. Which boundary should reject the result?', es: 'Intercambiá el destinatario del ID token y el de la API. ¿Qué límite debería rechazar el resultado?' }, [
    Q({ en: 'Where should Requests.Read be exposed?', es: '¿Dónde se debería exponer Requests.Read?' }, [{ en: 'Only in Angular source', es: 'Solo en el código de Angular' }, { en: 'On the PostgreSQL user', es: 'En el usuario de PostgreSQL' }, { en: 'On the API app registration', es: 'En el registro de la API' }], 2, { en: 'The resource defines the permissions clients can request.', es: 'El recurso define los permisos que los clientes pueden pedir.' }),
    Q({ en: 'Where can Angular safely hide a client secret?', es: '¿Dónde puede Angular esconder un client secret de forma segura?' }, [{ en: 'In an environment file included in its build', es: 'En un archivo de environment incluido en su build' }, { en: 'Nowhere in shipped browser code', es: 'En ninguna parte del código que llega al navegador' }, { en: 'In a minified module', es: 'En un módulo minificado' }], 1, { en: 'Anything shipped to the browser is available to its user.', es: 'Todo lo que llega al navegador está al alcance de su usuario.' }),
    Q({ en: 'What controls this API\'s expected access-token format?', es: '¿Qué controla el formato de access token que espera esta API?' }, [{ en: 'The resource configuration and its validation contract', es: 'La configuración del recurso y su contrato de validación' }, { en: 'Only the version of the authorization endpoint the SPA calls', es: 'Solo la versión del authorization endpoint al que llama la SPA' }, { en: 'Only whether the SPA requests the openid scope', es: 'Solo si la SPA pide el scope openid' }], 0, { en: 'The resource requests a token version, and Spring must validate its corresponding claims and issuer.', es: 'El recurso pide una versión de token, y Spring tiene que validar los claims y el issuer que le corresponden.' })
  ], study({ en: 'Predict what happens if an ID token intended for the SPA is sent to Spring.', es: 'Predecí qué pasa si a Spring le llega un ID token destinado a la SPA.' }, { en: 'Complete TENANT.md sections A through C. Set the API token version, expose both scopes, add the Approver user role and register the SPA callback. Use TENANT.md in the lab kit. Use a practice tenant and invented purchase requests.', es: 'Completá las secciones A a C de TENANT.md. Fijá la versión de token de la API, exponé los dos scopes, agregá el rol de usuario Approver y registrá el callback de la SPA. Usá TENANT.md del kit. Usá un tenant de práctica y solicitudes de compra inventadas.' }, { en: 'Two client IDs, the exact SPA redirect URI and delegated permissions referencing the API. No SPA secret exists.', es: 'Dos client IDs, la redirect URI exacta de la SPA y permisos delegados que referencian a la API. No existe ningún secreto de la SPA.' }, { en: 'Given SPA ID S and API ID A, annotate the expected aud of an ID token and an API access token. Diagnose a request where Spring expects S.', es: 'Dados el ID S de la SPA y el ID A de la API, anotá la aud esperada de un ID token y de un access token de la API. Diagnosticá un pedido en el que Spring espera S.' }), 'registration', 'tenant');

  add(2, 'authorization-code-pkce', { en: 'Follow the authorization code', es: 'Seguí el authorization code' }, { en: 'Understand the redirect without implementing an identity protocol yourself.', es: 'Entendé el redirect sin implementar vos un protocolo de identidad.' }, 'pkce', [
    F({ en: 'A request leaves the application', es: 'Un pedido sale de la aplicación' }, { en: 'MSAL creates a fresh verifier and its S256 challenge, then navigates to the tenant\'s authorization endpoint with the client, redirect URI and requested scopes. Entra handles sign-in and applicable policies. The application does not collect the Entra password. Returning to a registered callback does not by itself mean every later API operation is authorized.', es: 'MSAL crea un verifier nuevo y su challenge S256, y después navega al authorization endpoint del tenant con el cliente, la redirect URI y los scopes pedidos. Entra se ocupa del inicio de sesión y de las políticas que correspondan. La aplicación no recibe la contraseña de Entra. Volver a un callback registrado no significa, por sí solo, que cada operación posterior en la API esté autorizada.' }, { en: 'Let the identity provider handle the credentials.', es: 'Dejá que el proveedor de identidad maneje las credenciales.' }),
    F({ en: 'The code is exchanged', es: 'El code se canjea' }, { en: 'The authorization response carries a short-lived code. The client redeems it with the original verifier. A captured code without the verifier should not suffice. State correlates the response with the initiated interaction; the OIDC nonce binds identity-token evidence to the authentication request. These defenses serve different purposes, and the library manages their lifecycle.', es: 'La respuesta de autorización trae un code de vida corta. El cliente lo canjea con el verifier original. Un code capturado sin el verifier no tendría que alcanzar. State relaciona la respuesta con la interacción que la inició; el nonce de OIDC ata la evidencia del ID token al pedido de autenticación. Estas defensas sirven para cosas distintas, y la biblioteca maneja su ciclo de vida.' }, { en: 'PKCE binds code redemption to the initiating client instance.', es: 'PKCE ata el canje del code a la instancia del cliente que lo inició.' }),
    F({ en: 'Know the defense\'s limit', es: 'Conocé el límite de la defensa' }, { en: 'PKCE reduces the usefulness of intercepted authorization codes. It does not encrypt browser storage, prevent malicious script from acting inside the origin, or make a stolen bearer access token unusable. The fixture does not implement this flow. Its hashing exercise demonstrates the challenge relationship only; the tenant workbook observes a real redirect and exchange.', es: 'PKCE le quita utilidad a un authorization code interceptado. No cifra el almacenamiento del navegador, no impide que un script malicioso actúe dentro del origen ni vuelve inútil un bearer access token robado. El fixture no implementa este flujo. Su ejercicio de hash muestra solo la relación del challenge; el recorrido del tenant observa un redirect y un canje reales.' }, { en: 'A code-interception defense is not an XSS defense.', es: 'Una defensa contra la intercepción del code no es una defensa contra XSS.' })
  ], { en: 'Change whether the original verifier is available. Follow the code, then the resulting access token.', es: 'Cambiá si el verifier original está disponible. Seguí el code, y después el access token que resulta.' }, [
    Q({ en: 'A code is intercepted without its verifier. What does PKCE address?', es: 'Se intercepta un code sin su verifier. ¿Qué resuelve PKCE?' }, [{ en: 'Encrypting PostgreSQL rows', es: 'Cifrar las filas de PostgreSQL' }, { en: 'Blocking redemption with the wrong verifier', es: 'Bloquear el canje con el verifier equivocado' }, { en: 'Preventing every bearer-token replay', es: 'Impedir cualquier reutilización de un bearer token' }], 1, { en: 'The challenge is checked during code redemption; it is not a general browser security mechanism.', es: 'El challenge se verifica durante el canje del code; no es un mecanismo general de seguridad del navegador.' }),
    Q({ en: 'Where should the user enter their Entra password?', es: '¿Dónde tiene que escribir el usuario su contraseña de Entra?' }, [{ en: 'In the Angular API form', es: 'En el formulario de la API en Angular' }, { en: 'In Spring\'s request body', es: 'En el cuerpo del pedido a Spring' }, { en: 'At the trusted identity provider\'s sign-in page', es: 'En la página de inicio de sesión del proveedor de identidad de confianza' }], 2, { en: 'The client redirects; it does not collect or forward the user\'s password.', es: 'El cliente redirige; no recibe ni reenvía la contraseña del usuario.' }),
    Q({ en: 'Does the local hash exercise prove an Entra code exchange succeeded?', es: '¿El ejercicio local de hash prueba que un canje de code en Entra salió bien?' }, [{ en: 'No, it tests only the cryptographic relationship', es: 'No, solo prueba la relación criptográfica' }, { en: 'Yes, if the challenge has 43 characters', es: 'Sí, si el challenge tiene 43 caracteres' }, { en: 'Yes, because it uses SHA-256', es: 'Sí, porque usa SHA-256' }], 0, { en: 'A protocol exchange requires the actual endpoints and state checks, not just a hash.', es: 'Un canje del protocolo necesita los endpoints reales y las verificaciones de state, no solo un hash.' })
  ], lab('pkce', { en: 'Can a different verifier produce the same expected challenge in this experiment?', es: '¿Un verifier distinto puede producir el mismo challenge esperado en este experimento?' }, { en: 'PASS and an S256 challenge length of 43. No code exchange occurs.', es: 'PASS y un challenge S256 de 43 caracteres. No se canjea ningún code.' }, { en: 'Observe the real flow in TENANT.md. Do not export a browser network archive containing tokens, cookies or authorization codes.', es: 'Observá el flujo real en TENANT.md. No exportes un archivo de red del navegador que contenga tokens, cookies o authorization codes.' }), 'pkce');

  add(2, 'three-token-jobs', { en: 'Three token jobs', es: 'Tres trabajos de los tokens' }, { en: 'Identity, resource access and renewal are different jobs.', es: 'Identidad, acceso a un recurso y renovación son trabajos distintos.' }, 'tokens', [
    F({ en: 'ID token: a client sign-in result', es: 'ID token: el resultado del inicio de sesión para el cliente' }, { en: 'An ID token belongs to the OIDC relationship between Entra and the client. It can help the client present the signed-in account. It is not the credential our API accepts. In the separate-registration design its audience identifies the SPA, which gives Spring a concrete reason to reject it even if the signature is genuine.', es: 'Un ID token pertenece a la relación OIDC entre Entra y el cliente. Le puede servir al cliente para mostrar la cuenta que inició sesión. No es la credencial que acepta nuestra API. En el diseño con registros separados, su audiencia identifica a la SPA, y eso le da a Spring un motivo concreto para rechazarlo aunque la firma sea genuina.' }, { en: 'A genuine token can be the wrong token for this recipient.', es: 'Un token genuino puede ser el token equivocado para este destinatario.' }),
    F({ en: 'Access token: evidence for a resource', es: 'Access token: evidencia para un recurso' }, { en: 'Angular acquires an access token for the purchase API and sends it in the Authorization header. The API validates it and evaluates permissions. A Microsoft Graph token targets Microsoft Graph; the purchase API must reject it. The client should treat access tokens as opaque credentials rather than basing business decisions on their decoded contents.', es: 'Angular obtiene un access token para la API de compras y lo manda en el header Authorization. La API lo valida y evalúa los permisos. Un token de Microsoft Graph va dirigido a Microsoft Graph; la API de compras lo tiene que rechazar. El cliente tendría que tratar los access tokens como credenciales opacas, en lugar de basar decisiones de negocio en su contenido decodificado.' }, { en: 'Every access token has a recipient and a limited purpose.', es: 'Cada access token tiene un destinatario y un propósito limitado.' }),
    F({ en: 'Renewal belongs to the client library', es: 'La renovación le toca a la biblioteca del cliente' }, { en: 'A refresh token is used with the identity provider to obtain further tokens; it is not sent to the purchase API or database. MSAL manages the cache and renewal process. A JWT payload is base64url-encoded, not encrypted. Reading a payload proves neither its origin nor its validity. Keep raw tokens out of logs, URLs, screenshots and public decoding sites.', es: 'Un refresh token se usa con el proveedor de identidad para obtener más tokens; no se manda a la API de compras ni a la base de datos. MSAL maneja la caché y la renovación. El payload de un JWT está codificado en base64url, no cifrado. Leer un payload no prueba ni su origen ni su validez. Dejá los tokens crudos fuera de los logs, las URLs, las capturas y los sitios públicos de decodificación.' }, { en: 'Decoding is inspection. Validation is a security decision.', es: 'Decodificar es inspeccionar. Validar es una decisión de seguridad.' })
  ], { en: 'Choose ID, API or Graph token. Identify its recipient before looking at its claims.', es: 'Elegí el ID token, el de la API o el de Graph. Identificá su destinatario antes de mirar sus claims.' }, [
    Q({ en: 'Which token should Angular send to the purchase API?', es: '¿Qué token tiene que mandar Angular a la API de compras?' }, [{ en: 'An access token issued for that API', es: 'Un access token emitido para esa API' }, { en: 'Any token with the user\'s name', es: 'Cualquier token con el nombre del usuario' }, { en: 'The refresh token', es: 'El refresh token' }], 0, { en: 'The resource requires an access token intended for its audience and accepted contract.', es: 'El recurso exige un access token destinado a su audiencia y que cumpla el contrato que acepta.' }),
    Q({ en: 'You decode a JWT and see Approver. What have you established?', es: 'Decodificás un JWT y ves Approver. ¿Qué estableciste?' }, [{ en: 'The signature is trusted', es: 'Que la firma es de confianza' }, { en: 'The payload contains that string', es: 'Que el payload contiene ese texto' }, { en: 'The operation is permitted', es: 'Que la operación está permitida' }], 1, { en: 'Untrusted text can contain any role. Cryptographic validation and policy checks are still necessary.', es: 'Un texto no confiable puede contener cualquier rol. Siguen haciendo falta la validación criptográfica y las verificaciones de la política.' }),
    Q({ en: 'Where is a refresh token used?', es: '¿Dónde se usa un refresh token?' }, [{ en: 'As a JDBC password', es: 'Como contraseña de JDBC' }, { en: 'In every API Authorization header', es: 'En cada header Authorization hacia la API' }, { en: 'With the identity provider through the client library', es: 'Con el proveedor de identidad, a través de la biblioteca del cliente' }], 2, { en: 'Renewal credentials have a different destination and must not be propagated to ordinary resource APIs.', es: 'Las credenciales de renovación tienen otro destino y no se tienen que propagar a las API de recursos comunes.' })
  ], lab('tokens', { en: 'Will the fixture ID-token-shaped credential work at the API?', es: '¿La credencial del fixture con forma de ID token va a funcionar en la API?' }, { en: 'Decoded fixture claims, then 401 for the SPA audience and 200 for the API audience.', es: 'Los claims del fixture decodificados, después 401 para la audiencia de la SPA y 200 para la audiencia de la API.' }, { en: 'The shape is illustrative. The test establishes the API\'s audience check, not complete Entra ID-token behavior.', es: 'La forma es ilustrativa. La prueba establece la verificación de audiencia de la API, no el comportamiento completo de un ID token de Entra.' }), 'tokens');

  add(2, 'scopes-and-consent', { en: 'Scopes and consent', es: 'Scopes y consentimiento' }, { en: 'Permission granted to a client is not unlimited authority over a person\'s data.', es: 'Un permiso otorgado a un cliente no es autoridad ilimitada sobre los datos de una persona.' }, 'policy', [
    F({ en: 'A delegated permission', es: 'Un permiso delegado' }, { en: 'A scope is a permission the resource exposes for a client acting with a signed-in user. Our two delegated scopes are Requests.Read and Requests.Approve. Entra puts granted delegated scopes in the access token\'s space-delimited scp claim. Spring maps them to SCOPE_ authorities. A scope is not an SQL row filter.', es: 'Un scope es un permiso que expone el recurso para un cliente que actúa con un usuario que inició sesión. Nuestros dos scopes delegados son Requests.Read y Requests.Approve. Entra pone los scopes delegados otorgados en el claim scp del access token, separados por espacios. Spring los convierte en authorities SCOPE_. Un scope no es un filtro de filas de SQL.' }, { en: 'A delegated scope describes permitted client activity, not ownership.', es: 'Un scope delegado describe lo que el cliente puede hacer, no de quién es cada cosa.' }),
    F({ en: 'Consent is a separate decision', es: 'El consentimiento es una decisión aparte' }, { en: 'Consent records permission for the client to request access under the relevant tenant policies. Some permissions or policies need administrator consent; others may permit user consent. A prompt being accepted does not make the user an approver or transfer ownership of every purchase request. Our API still evaluates role, tenant and record state.', es: 'El consentimiento registra el permiso para que el cliente pida acceso, según las políticas del tenant que correspondan. Algunos permisos o políticas necesitan el consentimiento de un administrador; otras pueden permitir que consienta el usuario. Que se acepte un aviso no vuelve aprobador al usuario ni le transfiere la propiedad de todas las solicitudes de compra. Nuestra API igual evalúa el rol, el tenant y el estado del registro.' }, { en: 'Consent does not replace the application\'s authorization rules.', es: 'El consentimiento no reemplaza las reglas de autorización de la aplicación.' }),
    F({ en: 'Request only what the operation needs', es: 'Pedí solo lo que necesita la operación' }, { en: 'A production client can request scopes as features require them. The teaching client requests both course scopes so the experiment can isolate user roles and row rules. That choice is explicitly broader than a read-only feature needs. Removing an approval scope should deny approval while leaving a permitted read usable.', es: 'Un cliente de producción puede pedir scopes a medida que las funciones los necesitan. El cliente del curso pide los dos scopes para que el experimento pueda aislar los roles de usuario y las reglas de filas. Esa elección es, de forma explícita, más amplia de lo que necesita una función de solo lectura. Quitar el scope de aprobación tendría que rechazar la aprobación y dejar funcionando una lectura permitida.' }, { en: 'Evaluate the requested permission set, not just whether a prompt appeared.', es: 'Evaluá el conjunto de permisos pedidos, no solo si apareció un aviso.' })
  ], { en: 'Remove the approval scope while retaining the Approver role. Predict the approval response.', es: 'Quitá el scope de aprobación y conservá el rol Approver. Predecí la respuesta a la aprobación.' }, [
    Q({ en: 'What does scp contain in a delegated access token?', es: '¿Qué contiene scp en un access token delegado?' }, [{ en: 'Database table names', es: 'Nombres de tablas de la base de datos' }, { en: 'Granted delegated scope values', es: 'Los valores de los scopes delegados otorgados' }, { en: 'Every user role', es: 'Todos los roles del usuario' }], 1, { en: 'Scopes and roles have different claims and meanings.', es: 'Los scopes y los roles van en claims distintos y significan cosas distintas.' }),
    Q({ en: 'An administrator grants client consent. Can every user now approve?', es: 'Un administrador otorga el consentimiento para el cliente. ¿Ahora puede aprobar cualquier usuario?' }, [{ en: 'Yes, consent overrides app rules', es: 'Sí, el consentimiento pasa por encima de las reglas de la app' }, { en: 'Yes, if the user signs in again', es: 'Sí, si el usuario vuelve a iniciar sesión' }, { en: 'No, the API still requires the user role and resource rules', es: 'No, la API sigue exigiendo el rol de usuario y las reglas del recurso' }], 2, { en: 'Consent enables a client permission; it is not a blanket business entitlement.', es: 'El consentimiento habilita un permiso del cliente; no es un derecho de negocio general.' }),
    Q({ en: 'Which should a read-only feature normally request?', es: '¿Qué tendría que pedir normalmente una función de solo lectura?' }, [{ en: 'The least access needed for that feature', es: 'El acceso mínimo que necesita esa función' }, { en: 'Every exposed scope', es: 'Todos los scopes expuestos' }, { en: 'A database administrator role', es: 'Un rol de administrador de base de datos' }], 0, { en: 'Start with the operation\'s needs and broaden only for an explicit requirement.', es: 'Empezá por lo que necesita la operación y ampliá solo ante un requisito explícito.' })
  ], lab('scopes', { en: 'What happens with Approver plus Requests.Read but without Requests.Approve?', es: '¿Qué pasa con Approver y Requests.Read, pero sin Requests.Approve?' }, { en: 'Approval returns 403; reading the caller\'s own record still returns 200.', es: 'La aprobación devuelve 403; leer el registro propio de quien llama sigue devolviendo 200.' }, { en: 'The fixture supplies claims directly. It cannot prove that tenant consent issued them.', es: 'El fixture pone los claims directamente. No puede probar que los emitió el consentimiento del tenant.' }), 'consent');

  add(2, 'roles-and-resource-rules', { en: 'Roles and resource rules', es: 'Roles y reglas del recurso' }, { en: 'A role grants a category of power; a record still has its own constraints.', es: 'Un rol otorga una categoría de poder; un registro sigue teniendo sus propias restricciones.' }, 'policy', [
    F({ en: 'An application role', es: 'Un rol de aplicación' }, { en: 'Approver is an app role defined on the API registration, with Users as its allowed member type for this course. Assign it to the practice approver through the API Enterprise application. The API-targeted access token can then carry Approver in roles. A tenant administrator role is a different kind of authority and does not automatically mean purchase approver.', es: 'Approver es un app role definido en el registro de la API, con Users como tipo de miembro permitido en este curso. Asignáselo al aprobador de práctica a través de la entrada de la API en Enterprise applications (Aplicaciones empresariales). Desde ese momento, el access token dirigido a la API puede traer Approver en roles. Un rol de administrador del tenant es otro tipo de autoridad y no significa, por sí solo, ser aprobador de compras.' }, { en: 'Define roles in the resource whose policy consumes them.', es: 'Definí los roles en el recurso cuya política los usa.' }),
    F({ en: 'Role membership is only one predicate', es: 'Ser miembro de un rol es solo un predicado' }, { en: 'Our approver can approve a colleague\'s pending request in the same tenant. They cannot approve their own request or an already approved request. Spring checks the scope and role; SQL atomically checks the tenant, ownership relation and current state. This combination is a useful example of role-based and attribute-based conditions working together.', es: 'Nuestro aprobador puede aprobar la solicitud pendiente de un colega del mismo tenant. No puede aprobar su propia solicitud ni una que ya está aprobada. Spring verifica el scope y el rol; el SQL verifica de forma atómica el tenant, la relación de propiedad y el estado actual. Esta combinación es un buen ejemplo de condiciones basadas en roles y en atributos que trabajan juntas.' }, { en: 'Role-based access still needs object-level authorization.', es: 'El acceso basado en roles igual necesita autorización a nivel de objeto.' }),
    F({ en: 'Groups are not a free substitute', es: 'Los grupos no son un reemplazo gratis' }, { en: 'Groups can help administrators assign roles. Building API policy directly around a long groups claim adds concerns such as overage and directory lookups. The course keeps the runtime contract small: one explicit user role. Existing tokens can retain older role information until renewal or expiry; an assignment change is not a synchronous rewrite of tokens already issued.', es: 'Los grupos pueden ayudar a los administradores a asignar roles. Armar la política de la API directamente alrededor de un claim groups largo suma problemas como el overage y las consultas al directorio. El curso mantiene chico el contrato en tiempo de ejecución: un solo rol de usuario explícito. Los tokens existentes pueden conservar información de roles vieja hasta que se renuevan o vencen; un cambio de asignación no reescribe en el momento los tokens ya emitidos.' }, { en: 'A role assignment and an existing token can temporarily disagree.', es: 'Una asignación de rol y un token existente pueden no coincidir por un tiempo.' })
  ], { en: 'Keep scope and role but select the caller\'s own request. Why should approval still fail?', es: 'Conservá el scope y el rol, pero elegí la solicitud propia de quien llama. ¿Por qué igual tiene que fallar la aprobación?' }, [
    Q({ en: 'Why can a valid approver be denied?', es: '¿Por qué se le puede rechazar algo a un aprobador válido?' }, [{ en: 'The record rule may forbid this action', es: 'La regla del registro puede prohibir esta acción' }, { en: 'A role makes the JWT unsigned', es: 'Un rol deja el JWT sin firma' }, { en: 'Approval always needs a database superuser', es: 'Aprobar siempre necesita un superusuario de la base de datos' }], 0, { en: 'The role is necessary but the record must also satisfy the policy.', es: 'El rol es necesario, pero el registro también tiene que cumplir la política.' }),
    Q({ en: 'Which role belongs in this API\'s contract?', es: '¿Qué rol pertenece al contrato de esta API?' }, [{ en: 'Any directory administration role', es: 'Cualquier rol de administración del directorio' }, { en: 'Approver defined for the purchase API', es: 'Approver, definido para la API de compras' }, { en: 'A browser-local role string', es: 'Un texto de rol local del navegador' }], 1, { en: 'App-specific roles should come from the resource\'s verified token contract.', es: 'Los roles propios de la app tienen que salir del contrato de token verificado del recurso.' }),
    Q({ en: 'Removing an assignment necessarily changes an already issued JWT immediately. True?', es: 'Quitar una asignación cambia necesariamente, y en el momento, un JWT ya emitido. ¿Verdadero?' }, [{ en: 'Yes, every API request re-reads the assignment', es: 'Sí, cada pedido a la API vuelve a leer la asignación' }, { en: 'Yes, signatures update remotely', es: 'Sí, las firmas se actualizan a distancia' }, { en: 'No, token freshness and revocation behavior must be considered', es: 'No, hay que tener en cuenta la vigencia de los tokens y cómo se revocan' }], 2, { en: 'A signed token is a snapshot. Online policy changes need an explicit enforcement and renewal design.', es: 'Un token firmado es una foto. Los cambios de política en línea necesitan un diseño explícito de aplicación y de renovación.' })
  ], lab('roles', { en: 'Predict approval with no role, then self-approval with the role.', es: 'Predecí la aprobación sin rol, y después la autoaprobación con el rol.' }, { en: '403 without the role; 404 for self-approval despite scope and role.', es: '403 sin el rol; 404 para la autoaprobación, aunque haya scope y rol.' }, { en: 'This API uses 404 for a row that does not qualify. That does not identify which row predicate failed.', es: 'Esta API usa 404 para una fila que no califica. Eso no dice qué predicado de la fila falló.' }), 'roles');

  add(2, 'angular-and-msal', { en: 'Angular and MSAL', es: 'Angular y MSAL' }, { en: 'Let the library manage the protocol; keep the API destination explicit.', es: 'Dejá que la biblioteca maneje el protocolo; mantené explícito el destino en la API.' }, 'pkce', [
    F({ en: 'Initialize before asking for tokens', es: 'Inicializá antes de pedir tokens' }, { en: 'The sample loads public configuration, initializes PublicClientApplication, handles the redirect result and sets the active account from that result. It does not silently choose an arbitrary cached account when no active account exists. Login is an explicit action. The /redirect path runs the MSAL bridge and does not bootstrap the application or put a guard in front of the callback.', es: 'El ejemplo carga la configuración pública, inicializa PublicClientApplication, procesa el resultado del redirect y fija la cuenta activa a partir de ese resultado. Cuando no hay una cuenta activa, no elige en silencio una cuenta cualquiera de la caché. Iniciar sesión es una acción explícita. La ruta /redirect ejecuta el bridge de MSAL, y no arranca la aplicación ni pone un guard delante del callback.' }, { en: 'Account selection is part of the user experience and the request context.', es: 'Elegir la cuenta es parte de la experiencia del usuario y del contexto del pedido.' }),
    F({ en: 'Acquire for the operation', es: 'Pedí el token para la operación' }, { en: 'Before calling the API, the client asks acquireTokenSilent for the required API scopes and selected account. Silent acquisition may use the cache or contact Entra; it does not guarantee success without interaction. InteractionRequiredAuthError leads to an interactive redirect. Other failures are shown to the user rather than retried as a sign-in loop.', es: 'Antes de llamar a la API, el cliente le pide a acquireTokenSilent los scopes de la API que hacen falta, para la cuenta elegida. La obtención silenciosa puede usar la caché o consultar a Entra; no garantiza que salga bien sin interacción. InteractionRequiredAuthError lleva a un redirect interactivo. Las otras fallas se le muestran al usuario, en lugar de reintentarse en un bucle de inicio de sesión.' }, { en: 'Silent is an attempt, not an entitlement to a fresh token.', es: 'Silencioso es un intento, no un derecho a un token nuevo.' }),
    F({ en: 'Attach only to the intended destination', es: 'Adjuntalo solo al destino previsto' }, { en: 'The sample explicitly attaches the returned access token to a fixed API URL. An interceptor is another valid design when its protected-resource map is precise. Never attach the token to every outbound request. Session storage reduces persistence compared with local storage, but JavaScript running in the same origin can still act with the user\'s privileges.', es: 'El ejemplo adjunta de forma explícita el access token devuelto a una URL fija de la API. Un interceptor es otro diseño válido cuando su mapa de recursos protegidos es preciso. Nunca adjuntes el token a todos los pedidos salientes. El session storage dura menos que el local storage, pero un JavaScript que corre en el mismo origen igual puede actuar con los privilegios del usuario.' }, { en: 'Token delivery is a destination policy, not a convenience header.', es: 'Entregar el token es una política de destinos, no un header de conveniencia.' })
  ], { en: 'Trace the callback, then the API request. Which step actually sends the bearer credential?', es: 'Seguí el callback, y después el pedido a la API. ¿Qué paso es el que manda de verdad la credencial bearer?' }, [
    Q({ en: 'Silent acquisition requires interaction. What should the app do?', es: 'La obtención silenciosa necesita interacción. ¿Qué tiene que hacer la app?' }, [{ en: 'Retry forever in the background', es: 'Reintentar para siempre en segundo plano' }, { en: 'Send an ID token instead', es: 'Mandar un ID token en su lugar' }, { en: 'Use the library\'s supported interactive path', es: 'Usar el camino interactivo que admite la biblioteca' }], 2, { en: 'Some policies require user participation. Repeated silent retries do not satisfy them.', es: 'Algunas políticas exigen que participe el usuario. Repetir intentos silenciosos no las satisface.' }),
    Q({ en: 'Where should bearer tokens be attached?', es: '¿A qué se tienen que adjuntar los bearer tokens?' }, [{ en: 'Only to explicitly intended resource URLs', es: 'Solo a las URLs de recursos previstas de forma explícita' }, { en: 'To all requests from the browser', es: 'A todos los pedidos del navegador' }, { en: 'To static course assets', es: 'A los archivos estáticos del curso' }], 0, { en: 'The token must not leak to unrelated hosts or resources.', es: 'El token no se tiene que filtrar a hosts o recursos que no tienen nada que ver.' }),
    Q({ en: 'Does session storage prevent same-origin malicious script from using the session?', es: '¿El session storage impide que un script malicioso del mismo origen use la sesión?' }, [{ en: 'Yes, because it is per tab', es: 'Sí, porque es por pestaña' }, { en: 'No, script execution remains a threat', es: 'No, la ejecución de scripts sigue siendo una amenaza' }, { en: 'Yes, if PKCE was used', es: 'Sí, si se usó PKCE' }], 1, { en: 'Storage lifetime and script isolation are different properties.', es: 'Cuánto dura el almacenamiento y el aislamiento de los scripts son propiedades distintas.' })
  ], study({ en: 'Predict which HTTP request carries the API access token.', es: 'Predecí qué pedido HTTP lleva el access token de la API.' }, { en: 'Complete TENANT.md section D, open the Angular application, sign in and read an owned request. Inspect only destinations and statuses, not copied credentials. Use TENANT.md in the lab kit. Use a practice tenant and invented purchase requests.', es: 'Completá la sección D de TENANT.md, abrí la aplicación Angular, iniciá sesión y leé una solicitud propia. Inspeccioná solo destinos y códigos de estado, no credenciales copiadas. Usá TENANT.md del kit. Usá un tenant de práctica y solicitudes de compra inventadas.' }, { en: 'A callback to /redirect, return to the application and a bearer request to the API URL.', es: 'Un callback a /redirect, la vuelta a la aplicación y un pedido bearer a la URL de la API.' }, { en: 'Read frontend/src/main.ts. Mark initialize, handleRedirectPromise, acquireTokenSilent and the fixed fetch destination. Explain what changes when interaction is required.', es: 'Leé frontend/src/main.ts. Marcá initialize, handleRedirectPromise, acquireTokenSilent y el destino fijo del fetch. Explicá qué cambia cuando hace falta interacción.' }), 'msal', 'tenant');

  add(2, 'windows-sign-in-and-prt', { en: 'Windows sign-in and the Primary Refresh Token', es: 'Inicio de sesión de Windows y Primary Refresh Token' }, { en: 'On a device joined to Entra, Windows holds a token before the app asks for one.', es: 'En un dispositivo unido a Entra, Windows ya tiene un token antes de que la app pida uno.' }, 'device', [
    F({ en: 'Windows signs in to Entra first', es: 'Windows inicia sesión en Entra primero' }, { en: 'On a Windows device joined to Entra, the sign-in screen does more than unlock the desktop. LogonUI hands the credentials to the Local Security Authority, whose CloudAP provider passes them to its Microsoft Entra plugin. The plugin gets a nonce from Entra, signs a request with the device key held in the TPM and sends it. Entra checks the credentials, the nonce and the device, then issues a Primary Refresh Token (PRT) and a session key encrypted for this device. The TPM unwraps the session key and wraps it again with its own key; CloudAP keeps both in its cache. A sign-in with Windows Hello for Business adds an MFA claim to the PRT.', es: 'En un dispositivo Windows unido a Entra, la pantalla de inicio de sesión hace más que desbloquear el escritorio. LogonUI le pasa las credenciales a la Local Security Authority, cuyo proveedor CloudAP se las pasa a su plugin de Microsoft Entra. El plugin obtiene un nonce de Entra, firma un pedido con la clave del dispositivo que guarda el TPM y lo manda. Entra verifica las credenciales, el nonce y el dispositivo, y después emite un Primary Refresh Token (PRT) y una session key cifrada para este dispositivo. El TPM desenvuelve la session key y la vuelve a envolver con su propia clave; CloudAP guarda los dos en su caché. Un inicio de sesión con Windows Hello for Business le agrega al PRT un claim de MFA.' }, { en: 'The first Entra token of the day belongs to the device\'s sign-in broker, not to an application.', es: 'El primer token de Entra del día es del intermediario de inicio de sesión del dispositivo, no de una aplicación.' }),
    F({ en: 'The browser borrows the session, never the PRT', es: 'El navegador usa la sesión prestada, nunca el PRT' }, { en: 'When MSAL sends the tab to /authorize, Edge with a profile signed in to the work account, or Chrome with the Microsoft Single Sign On extension, recognizes an Entra sign-in URL and asks CloudAP for a PRT cookie. CloudAP builds it with the nonce from that URL and has the TPM sign it with the session key. The browser sends it in the x-ms-RefreshTokenCredential header; page scripts never see it. Entra validates the signature, the nonce and the device, signs Alice in without a password and sets its own session cookie, bound to the device. The code, PKCE and tokens then follow as before. Private windows do not use the PRT.', es: 'Cuando MSAL manda la pestaña a /authorize, Edge con un perfil que tiene iniciada la sesión de la cuenta de trabajo, o Chrome con la extensión Microsoft Single Sign On, reconoce una URL de inicio de sesión de Entra y le pide a CloudAP una PRT cookie. CloudAP la arma con el nonce de esa URL y hace que el TPM la firme con la session key. El navegador la manda en el header x-ms-RefreshTokenCredential; los scripts de la página nunca la ven. Entra valida la firma, el nonce y el dispositivo, le inicia la sesión a Alice sin contraseña y fija su propia cookie de sesión, atada al dispositivo. Después siguen el code, PKCE y los tokens, como antes. Las ventanas privadas no usan el PRT.' }, { en: 'Single sign-on changes how Alice proves who she is, not which tokens the app receives.', es: 'El single sign-on cambia cómo Alice prueba quién es, no qué tokens recibe la app.' }),
    F({ en: 'Each credential has its own place and clock', es: 'Cada credencial tiene su lugar y su reloj' }, { en: 'Device keys stay in the TPM. The PRT and its session key stay in CloudAP\'s cache; the PRT is valid for 90 days and CloudAP renews it at Windows sign-in every 4 hours. A PRT cookie exists for one request. Entra\'s session cookie lives in the browser\'s cookies for login.microsoftonline.com. The ID, access and refresh tokens live in the tab\'s sessionStorage, and a refresh token issued to a SPA lasts 24 hours without sliding. Deleting or disabling the user or the device, or a password change when the PRT came from the password, invalidates the PRT; none of this recalls an access token already issued. Native applications ask WAM, the Windows token broker, which keeps their refresh tokens encrypted with DPAPI. This browser app does not use it.', es: 'Las claves del dispositivo quedan en el TPM. El PRT y su session key quedan en la caché de CloudAP; el PRT vale 90 días y CloudAP lo renueva al iniciar sesión en Windows cada 4 horas. Una PRT cookie existe para un solo pedido. La cookie de sesión de Entra vive en las cookies del navegador para login.microsoftonline.com. El ID token, el access token y el refresh token viven en el sessionStorage de la pestaña, y un refresh token emitido para una SPA dura 24 horas, en una ventana que no se corre. Borrar o deshabilitar el usuario o el dispositivo, o un cambio de contraseña cuando el PRT salió de la contraseña, invalida el PRT; nada de esto retira un access token ya emitido. Las aplicaciones nativas le piden a WAM, el intermediario de tokens de Windows, que guarda sus refresh tokens cifrados con DPAPI. Esta app de navegador no lo usa.' }, { en: 'For every credential, name who issues it, where it waits and when it stops working.', es: 'Para cada credencial, nombrá quién la emite, dónde espera y cuándo deja de servir.' })
  ], { en: 'Choose the moment, then the device and the browser. Predict whether /authorize asks Alice for a password before you read the result.', es: 'Elegí el momento, después el dispositivo y el navegador. Predecí si /authorize le pide una contraseña a Alice antes de leer el resultado.' }, [
    Q({ en: 'Where does the PRT stay on a device joined to Entra?', es: '¿Dónde queda el PRT en un dispositivo unido a Entra?' }, [{ en: 'In the tab\'s sessionStorage, next to MSAL\'s tokens', es: 'En el sessionStorage de la pestaña, junto a los tokens de MSAL' }, { en: 'In CloudAP\'s cache inside LSA, with a session key protected by the TPM', es: 'En la caché de CloudAP dentro de LSA, con una session key protegida por el TPM' }, { en: 'In the browser\'s cookies for login.microsoftonline.com', es: 'En las cookies del navegador para login.microsoftonline.com' }], 1, { en: 'CloudAP receives the PRT at Windows sign-in and keeps it with the TPM-protected session key. The browser and the app only ever see values derived from it.', es: 'CloudAP recibe el PRT al iniciar sesión en Windows y lo guarda con la session key protegida por el TPM. El navegador y la app solo llegan a ver valores derivados de él.' }),
    Q({ en: 'What does the browser add to the request to /authorize to use the device session?', es: '¿Qué le agrega el navegador al pedido a /authorize para usar la sesión del dispositivo?' }, [{ en: 'A PRT cookie in x-ms-RefreshTokenCredential, signed with the session key', es: 'Una PRT cookie en x-ms-RefreshTokenCredential, firmada con la session key' }, { en: 'The PRT itself, in an Authorization header', es: 'El PRT mismo, en un header Authorization' }, { en: 'Alice\'s Windows password, encrypted by the TPM', es: 'La contraseña de Windows de Alice, cifrada por el TPM' }], 0, { en: 'CloudAP builds a PRT cookie for that request and its nonce. The PRT, the session key and the password stay on the device.', es: 'CloudAP arma una PRT cookie para ese pedido y su nonce. El PRT, la session key y la contraseña quedan en el dispositivo.' }),
    Q({ en: 'Alice signed in to the app without typing a password. What reaches the purchase API?', es: 'Alice inició sesión en la app sin escribir una contraseña. ¿Qué le llega a la API de compras?' }, [{ en: 'The PRT, so the API can trust the device', es: 'El PRT, así la API puede confiar en el dispositivo' }, { en: 'Entra\'s session cookie', es: 'La cookie de sesión de Entra' }, { en: 'An access token for the API\'s audience, validated as always', es: 'Un access token para la audiencia de la API, validado como siempre' }], 2, { en: 'Single sign-on changes how Entra authenticates Alice. The API still receives, and checks, an access token issued for it.', es: 'El single sign-on cambia cómo Entra autentica a Alice. La API igual recibe, y verifica, un access token emitido para ella.' })
  ], [
    S({ en: 'Predict the sign-in', es: 'Predecí el inicio de sesión' }, { en: 'Write two predictions before touching a device. On a Windows device joined to the tenant, will the app ask Alice for a password in a browser profile signed in to her work account? And in a private window? Name the credential that makes the difference.', es: 'Escribí dos predicciones antes de tocar un dispositivo. En un dispositivo Windows unido al tenant, ¿la app le va a pedir una contraseña a Alice en un perfil del navegador que tiene iniciada la sesión de su cuenta de trabajo? ¿Y en una ventana privada? Nombrá la credencial que marca la diferencia.' }, { en: 'Two predictions and the credential that decides them.', es: 'Dos predicciones y la credencial que las decide.' }),
    S({ en: 'Read the device state', es: 'Leé el estado del dispositivo' }, { en: 'On a Windows 10 or 11 device joined to Entra, open a terminal as the signed-in user, not as administrator, and run the reference command. Read three lines only, and do not copy the output anywhere: it names the device, the tenant and the user.', es: 'En un dispositivo Windows 10 u 11 unido a Entra, abrí una terminal como el usuario con la sesión iniciada, no como administrador, y ejecutá el comando de referencia. Leé solo tres líneas, y no copies la salida a ningún lado: nombra el dispositivo, el tenant y el usuario.' }, { en: 'AzureAdJoined : YES under Device State, AzureAdPrt : YES under SSO State, and TpmProtected under Device Details.', es: 'AzureAdJoined : YES en Device State, AzureAdPrt : YES en SSO State, y TpmProtected en Device Details.' }, 'dsregcmd /status'),
    S({ en: 'Follow the tenant workbook', es: 'Seguí el recorrido del tenant' }, { en: 'Complete TENANT.md section F on a device joined to your practice tenant: sign in to the Angular application in Edge with a profile signed in as Alice, then in an InPrivate window. Use a practice tenant and invented purchase requests.', es: 'Completá la sección F de TENANT.md en un dispositivo unido a tu tenant de práctica: iniciá sesión en la aplicación Angular en Edge con un perfil que tiene iniciada la sesión de Alice, y después en una ventana InPrivate. Usá un tenant de práctica y solicitudes de compra inventadas.' }, { en: 'In the signed-in profile, the account picker the app asks for and no password request. In the InPrivate window, a credential request.', es: 'En el perfil con la sesión iniciada, el selector de cuentas que pide la app y ningún pedido de contraseña. En la ventana InPrivate, un pedido de credenciales.' }),
    S({ en: 'Account-free case study', es: 'Caso de estudio sin cuenta' }, { en: 'Use journeys A, B and C of the big picture. For the device keys, the PRT, the session key, the PRT cookie, Entra\'s session cookie and the ID, access and refresh tokens, write who issues each one, where it waits and when it stops working.', es: 'Usá los recorridos A, B y C del panorama. Para las claves del dispositivo, el PRT, la session key, la PRT cookie, la cookie de sesión de Entra y el ID token, el access token y el refresh token, escribí quién emite cada uno, dónde espera y cuándo deja de servir.' }, { en: 'Label this route CASE STUDY. It demonstrates reasoning, not an Entra execution.', es: 'Marcá este recorrido como CASO DE ESTUDIO. Demuestra razonamiento, no una ejecución en Entra.' }),
    S({ en: 'Explain the result', es: 'Explicá el resultado' }, { en: 'Draw the before and after. Mark what Windows holds, what the browser holds, what the tab holds and what the API receives. Keep raw tokens, cookies and device identifiers out of the notebook.', es: 'Dibujá el antes y el después. Marcá qué tiene Windows, qué tiene el navegador, qué tiene la pestaña y qué recibe la API. Dejá los tokens crudos, las cookies y los identificadores del dispositivo fuera del cuaderno.' }, { en: 'State the observation route and one guarantee it cannot establish: dsregcmd shows that a PRT exists, not what Entra will decide for the app.', es: 'Indicá el recorrido de observación y una garantía que no puede establecer: dsregcmd muestra que existe un PRT, no qué va a decidir Entra para la app.' })
  ], 'prt', 'tenant');

  add(3, 'validate-the-token', { en: 'Validate before trusting', es: 'Validá antes de confiar' }, { en: 'A signature is one check in a larger resource-server contract.', es: 'Una firma es una verificación dentro de un contrato de resource server más amplio.' }, 'tokens', [
    F({ en: 'Start from configured trust', es: 'Empezá por la confianza configurada' }, { en: 'Spring uses the configured issuer\'s metadata and public signing keys. It must not choose a trusted issuer or key URL solely from an untrusted token. The signature protects the signed bytes; the audience binds those bytes to a recipient; the issuer binds them to an authority. Key rotation is normal, so the decoder uses a JWK source rather than a hand-copied permanent key.', es: 'Spring usa los metadatos y las claves públicas de firma del issuer configurado. No tiene que elegir un issuer de confianza ni una URL de claves solo a partir de un token no confiable. La firma protege los bytes firmados; la audiencia ata esos bytes a un destinatario; el issuer los ata a una autoridad. La rotación de claves es normal, así que el decoder usa una fuente de JWK en lugar de una clave permanente copiada a mano.' }, { en: 'A key is trusted because of configuration and discovery, not because the token points to it.', es: 'Una clave es de confianza por la configuración y el discovery, no porque el token la señale.' }),
    F({ en: 'Validate the full contract', es: 'Validá el contrato completo' }, { en: 'The sample keeps Spring\'s issuer and timestamp validators, then adds audience, tenant, v2 format, allowed SPA client and a well-formed oid. It requires time claims rather than accepting a missing expiration. The timestamp validator allows a small clock skew; the tests use values well beyond it. A genuine token from a different client or for a different resource is still rejected.', es: 'El ejemplo conserva los validadores de issuer y de tiempo de Spring, y después agrega audiencia, tenant, formato v2, el cliente SPA permitido y un oid bien formado. Exige los claims de tiempo, en lugar de aceptar que falte el vencimiento. El validador de tiempo admite un pequeño desfasaje de reloj; las pruebas usan valores muy por encima. Un token genuino de otro cliente, o para otro recurso, igual se rechaza.' }, { en: 'Custom validation must add to, not accidentally replace, the defaults.', es: 'La validación propia tiene que sumarse a los valores por defecto, no reemplazarlos sin querer.' }),
    F({ en: 'Validation has operational dependencies', es: 'La validación tiene dependencias operativas' }, { en: 'A decoder may cache public keys, but key discovery and refresh can require network access. Failure to obtain a key can prevent acceptance; that is not permission to skip verification. Diagnose issuer metadata, key ID, clock and audience without logging the credential. A production deployment needs explicit timeout, monitoring and availability decisions.', es: 'Un decoder puede guardar las claves públicas en caché, pero descubrirlas y renovarlas puede necesitar acceso a la red. Si no consigue una clave, puede no aceptar el token; eso no es permiso para saltear la verificación. Diagnosticá los metadatos del issuer, el key ID, el reloj y la audiencia sin registrar la credencial en los logs. Un despliegue de producción necesita decisiones explícitas de timeout, monitoreo y disponibilidad.' }, { en: 'An outage must not become a fail-open authentication path.', es: 'Una caída no se puede convertir en un camino de autenticación que falla abierto.' })
  ], { en: 'Change the audience or signature. Follow the rejection before any scope or SQL check.', es: 'Cambiá la audiencia o la firma. Seguí el rechazo antes de cualquier verificación de scope o de SQL.' }, [
    Q({ en: 'A signature is valid but aud names Graph. What should Spring do?', es: 'Una firma es válida pero aud nombra a Graph. ¿Qué tiene que hacer Spring?' }, [{ en: 'Accept it because Microsoft signed it', es: 'Aceptarlo, porque lo firmó Microsoft' }, { en: 'Reject it because this API is not the audience', es: 'Rechazarlo, porque esta API no es la audiencia' }, { en: 'Accept it if a permission name resembles this API\'s scope', es: 'Aceptarlo si el nombre de un permiso se parece a un scope de esta API' }], 1, { en: 'A signature alone does not authorize token reuse at another resource.', es: 'Una firma, sola, no autoriza a reutilizar un token en otro recurso.' }),
    Q({ en: 'Adding an audience validator should do what to timestamp validation?', es: 'Agregar un validador de audiencia, ¿qué le tendría que hacer a la validación de tiempo?' }, [{ en: 'Preserve it', es: 'Conservarla' }, { en: 'Replace it', es: 'Reemplazarla' }, { en: 'Disable it during key rotation', es: 'Deshabilitarla durante la rotación de claves' }], 0, { en: 'The checks are cumulative. Accidentally replacing defaults can accept expired tokens.', es: 'Las verificaciones se suman. Reemplazar los valores por defecto sin querer puede hacer que se acepten tokens vencidos.' }),
    Q({ en: 'Where should the decoder obtain its trusted issuer?', es: '¿De dónde tiene que sacar el decoder su issuer de confianza?' }, [{ en: 'From any iss in the request token', es: 'De cualquier iss del token del pedido' }, { en: 'From a caller-supplied query parameter', es: 'De un parámetro de la query que manda quien llama' }, { en: 'From the configured trust policy', es: 'De la política de confianza configurada' }], 2, { en: 'Untrusted input cannot nominate its own authority.', es: 'Una entrada no confiable no puede nombrar su propia autoridad.' })
  ], lab('signature', { en: 'Would a correctly shaped token with the wrong signing key pass?', es: '¿Pasaría un token con la forma correcta pero firmado con la clave equivocada?' }, { en: 'Forged signature: 401. Untrusted issuer: 401.', es: 'Firma falsificada: 401. Issuer no confiable: 401.' }, { en: 'The fixture key and issuer are local. This verifies the configured Spring checks, not Entra signing-key rotation.', es: 'La clave y el issuer del fixture son locales. Esto verifica las verificaciones configuradas en Spring, no la rotación de claves de firma de Entra.' }), 'spring');

  add(3, 'claims-to-authorities', { en: 'From claims to Spring authorities', es: 'De los claims a las authorities de Spring' }, { en: 'Preserve the meaning of each claim while translating it into policy.', es: 'Conservá el significado de cada claim al traducirlo a una política.' }, 'policy', [
    F({ en: 'Claims are not annotations', es: 'Los claims no son anotaciones' }, { en: 'A decoded claim does not automatically activate a Spring method rule. The JwtAuthenticationConverter produces the authorities the policy evaluates. The standard scope converter creates SCOPE_Requests.Read and SCOPE_Requests.Approve. Our additional converter maps the recognized Approver value to ROLE_Approver without discarding the scopes.', es: 'Un claim decodificado no activa por sí solo una regla de método de Spring. El JwtAuthenticationConverter produce las authorities que evalúa la política. El conversor estándar de scopes crea SCOPE_Requests.Read y SCOPE_Requests.Approve. Nuestro conversor adicional convierte el valor reconocido Approver en ROLE_Approver sin descartar los scopes.' }, { en: 'Trace the claim, conversion and policy as three separate steps.', es: 'Seguí el claim, la conversión y la política como tres pasos separados.' }),
    F({ en: 'Be explicit about prefixes', es: 'Sé explícito con los prefijos' }, { en: 'The method uses hasAuthority with exact strings. In Spring, hasRole conventionally adds the ROLE_ prefix, so mixing it carelessly with already prefixed names can create a mismatch. Only the recognized API role is mapped here. Directory-wide administrative claims and arbitrary browser state are not treated as purchase approval authority.', es: 'El método usa hasAuthority con textos exactos. En Spring, hasRole agrega por convención el prefijo ROLE_, así que mezclarlo sin cuidado con nombres que ya tienen prefijo puede crear una discrepancia. Acá se convierte solo el rol reconocido de la API. Los claims de administración de todo el directorio y cualquier estado del navegador no se tratan como autoridad para aprobar compras.' }, { en: 'The authority string must match the policy\'s vocabulary exactly.', es: 'El texto de la authority tiene que coincidir exactamente con el vocabulario de la política.' }),
    F({ en: 'Reject the wrong access model', es: 'Rechazá el modelo de acceso equivocado' }, { en: 'The sample endpoints require delegated scopes, so an app-only token with roles but no scp cannot act as a person. This is a deliberate contract. A background job would need a separate application permission and a separately designed endpoint policy. Replacing AND with OR to make a failing call work would erase that distinction.', es: 'Los endpoints del ejemplo exigen scopes delegados, así que un token app-only con roles pero sin scp no puede actuar como una persona. Es un contrato deliberado. Un proceso en segundo plano necesitaría un permiso de aplicación aparte y una política de endpoint diseñada aparte. Reemplazar AND por OR para que funcione una llamada que falla borraría esa distinción.' }, { en: 'A machine identity must not acquire user powers by a convenient mapping.', es: 'Una identidad de máquina no puede ganar poderes de usuario por una conversión cómoda.' })
  ], { en: 'Try scope only, role only, then both. Predict the operation gate separately from the row gate.', es: 'Probá solo el scope, solo el rol y después los dos. Predecí el control de la operación por separado del control de la fila.' }, [
    Q({ en: 'What does ROLE_Approver represent in this sample?', es: '¿Qué representa ROLE_Approver en este ejemplo?' }, [{ en: 'A mapped, recognized API app role', es: 'Un app role de la API, reconocido y convertido' }, { en: 'Any Entra administrator', es: 'Cualquier administrador de Entra' }, { en: 'A PostgreSQL role', es: 'Un rol de PostgreSQL' }], 0, { en: 'The converter has a narrow mapping from the token\'s Approver value.', es: 'El conversor tiene una conversión acotada a partir del valor Approver del token.' }),
    Q({ en: 'Why is an app-only role insufficient here?', es: '¿Por qué acá no alcanza con un rol app-only?' }, [{ en: 'It always has an invalid signature', es: 'Siempre tiene una firma inválida' }, { en: 'It lacks the delegated scope required by these user endpoints', es: 'Le falta el scope delegado que exigen estos endpoints de usuario' }, { en: 'Its JSON cannot be decoded', es: 'Su JSON no se puede decodificar' }], 1, { en: 'The authenticated token can still fail the endpoint\'s access-model policy.', es: 'El token autenticado igual puede no cumplir la política de modelo de acceso del endpoint.' }),
    Q({ en: 'A role mapping accidentally drops all scope authorities. What happens?', es: 'Una conversión de roles descarta sin querer todas las authorities de scope. ¿Qué pasa?' }, [{ en: 'Authorization becomes stronger automatically', es: 'La autorización se vuelve más fuerte sola' }, { en: 'Every signed token works', es: 'Funciona cualquier token firmado' }, { en: 'Delegated scope checks can fail despite the scp claim', es: 'Las verificaciones de scope delegado pueden fallar aunque esté el claim scp' }], 2, { en: 'Policies evaluate converted authorities, not every raw claim directly.', es: 'Las políticas evalúan las authorities convertidas, no cada claim crudo directamente.' })
  ], lab('delegation', { en: 'Can a roles-only token approve through this delegated endpoint?', es: '¿Un token que solo tiene roles puede aprobar a través de este endpoint delegado?' }, { en: 'App-only token: 403. Wrong client: 401.', es: 'Token app-only: 403. Cliente equivocado: 401.' }, { en: 'These checks implement the chosen single-client contract. They are not universal requirements for every Entra API.', es: 'Estas verificaciones implementan el contrato elegido, de un solo cliente. No son requisitos universales para cualquier API de Entra.' }), 'spring-method');

  add(3, 'read-the-http-result', { en: 'Read a denial correctly', es: 'Leé bien un rechazo' }, { en: 'Separate invalid credentials, missing permission and hidden resources.', es: 'Separá credenciales inválidas, permisos que faltan y recursos ocultos.' }, 'boundaries', [
    F({ en: '401: accepted authentication is missing', es: '401: falta una autenticación aceptada' }, { en: 'The sample sends 401 when a protected request lacks an accepted bearer token: absent, expired, wrong audience or otherwise invalid. A resource-server response may contain a WWW-Authenticate challenge. Repeated sign-in is not the right fix for an API configured with the SPA audience; configuration errors require configuration changes.', es: 'El ejemplo responde 401 cuando a un pedido protegido le falta un bearer token aceptado: ausente, vencido, con la audiencia equivocada o inválido por otro motivo. Una respuesta de resource server puede traer un challenge WWW-Authenticate. Volver a iniciar sesión una y otra vez no arregla una API configurada con la audiencia de la SPA; los errores de configuración necesitan cambios de configuración.' }, { en: 'First identify whether the request carried the intended credential.', es: 'Primero identificá si el pedido llevaba la credencial prevista.' }),
    F({ en: '403: the operation requirement failed', es: '403: falló el requisito de la operación' }, { en: 'A valid delegated token without Requests.Approve or Approver is authenticated but lacks a required operation authority. The API returns 403. A browser can also show 403 for a rejected CORS preflight, which occurs at a different boundary. Inspect the method and the request that actually failed before interpreting a number in isolation.', es: 'Un token delegado válido sin Requests.Approve o sin Approver está autenticado, pero le falta una authority que exige la operación. La API devuelve 403. Un navegador también puede mostrar 403 por un preflight de CORS rechazado, que pasa en otro límite. Inspeccioná el método y el pedido que falló de verdad antes de interpretar un número aislado.' }, { en: 'Status, method and boundary belong together.', es: 'El código de estado, el método y el límite van juntos.' }),
    F({ en: '404: avoid a record-existence oracle', es: '404: no regalar un oráculo de existencia de registros' }, { en: 'The read query only returns a row owned by the validated subject in the validated tenant. Missing and unauthorized records both produce 404. Approval also uses 404 when no row meets its complete predicate, including pending status and not-owning. This is the sample\'s deliberate disclosure policy, not a universal claim that every authorization failure must be 404.', es: 'La consulta de lectura solo devuelve una fila cuyo dueño es el sujeto validado, en el tenant validado. Un registro que no existe y uno no autorizado dan los dos 404. La aprobación también usa 404 cuando ninguna fila cumple su predicado completo, que incluye el estado pendiente y no ser el dueño. Es la política de divulgación deliberada del ejemplo, no una regla universal de que todo fallo de autorización tenga que ser 404.' }, { en: 'A public error contract can reveal less than the internal audit trail.', es: 'Un contrato de errores público puede revelar menos que el registro interno de auditoría.' })
  ], { en: 'Choose the failing boundary and predict the status before revealing it.', es: 'Elegí el límite que falla y predecí el código de estado antes de mostrarlo.' }, [
    Q({ en: 'An expired token reaches a protected endpoint. Expected status here?', es: 'Un token vencido llega a un endpoint protegido. ¿Qué código de estado se espera acá?' }, ['404', '403', '401'], 2, { en: 'The request has no accepted authentication evidence.', es: 'El pedido no tiene evidencia de autenticación aceptada.' }),
    Q({ en: 'A valid user token lacks Approver. Expected approval status?', es: 'A un token de usuario válido le falta Approver. ¿Qué código de estado se espera para aprobar?' }, ['403', { en: '200 because sign-in succeeded', es: '200, porque el inicio de sesión salió bien' }, { en: '401 because every denial is authentication', es: '401, porque todo rechazo es de autenticación' }], 0, { en: 'The operation authority check fails after authentication.', es: 'La verificación de authority de la operación falla después de la autenticación.' }),
    Q({ en: 'A 404 for request 42 proves what to Alice?', es: '¿Qué le prueba a Alice un 404 para la solicitud 42?' }, [{ en: 'That request 42 never existed', es: 'Que la solicitud 42 nunca existió' }, { en: 'That no qualifying row was returned to her', es: 'Que no se le devolvió ninguna fila que califique' }, { en: 'That her token expired', es: 'Que su token venció' }], 1, { en: 'The response intentionally avoids revealing whether the row exists outside her policy.', es: 'La respuesta evita a propósito revelar si la fila existe fuera de su política.' })
  ], lab('http', { en: 'Will the unauthenticated response challenge the caller? Will the hidden row reveal its description?', es: '¿La respuesta sin autenticación le va a mandar un challenge a quien llama? ¿La fila oculta va a revelar su descripción?' }, { en: '401 with a Bearer challenge; 404 without the protected description.', es: '401 con un challenge Bearer; 404 sin la descripción protegida.' }, { en: 'The public response is not a complete audit record. Production telemetry should retain safe reason categories and correlation IDs.', es: 'La respuesta pública no es un registro de auditoría completo. La telemetría de producción tendría que conservar categorías de motivo seguras e IDs de correlación.' }), 'http');

  add(4, 'ownership-and-idor', { en: 'Ownership is an authorization rule', es: 'La propiedad es una regla de autorización' }, { en: 'Knowing an identifier does not entitle the caller to its row.', es: 'Conocer un identificador no le da derecho a quien llama a su fila.' }, 'rows', [
    F({ en: 'The tempting incomplete query', es: 'La consulta incompleta que tienta' }, { en: 'A request arrives for /api/requests/42. SELECT by id alone answers which row was requested, but not whether the caller may read it. Sequential IDs make guessing easy; replacing them with UUIDs may reduce guessability but does not establish permission. This class of missing object-level check is often called IDOR or broken object-level authorization.', es: 'Llega un pedido a /api/requests/42. Un SELECT solo por id responde qué fila se pidió, pero no si quien llama la puede leer. Los IDs secuenciales hacen fácil adivinar; reemplazarlos por UUIDs puede hacerlos más difíciles de adivinar, pero no establece ningún permiso. A esta clase de verificación por objeto que falta se la suele llamar IDOR o broken object-level authorization.' }, { en: 'An unpredictable ID is not a permission check.', es: 'Un ID impredecible no es una verificación de permisos.' }),
    F({ en: 'Derive identity from the accepted principal', es: 'Sacá la identidad del principal aceptado' }, { en: 'The sample query combines id with tenant_id and owner_oid taken from the validated Jwt principal. A caller cannot select their authority by supplying an email, owner header or tenant query parameter. Request 42 belongs to Bob, so Alice gets no qualifying row even though she has Requests.Read. Bob can retrieve it with his own accepted identity.', es: 'La consulta del ejemplo combina el id con tenant_id y owner_oid tomados del principal Jwt validado. Quien llama no puede elegir su autoridad mandando un email, un header de dueño o un parámetro de tenant en la query. La solicitud 42 es de Bob, así que Alice no obtiene ninguna fila que califique aunque tenga Requests.Read. Bob la puede obtener con su propia identidad aceptada.' }, { en: 'Client input selects a target; trusted context constrains access.', es: 'La entrada del cliente elige un destino; el contexto de confianza restringe el acceso.' }),
    F({ en: 'Carry policy through every data path', es: 'Llevá la política por cada camino a los datos' }, { en: 'Lists, exports, search, counts and nested resources need the same care as an individual read. A system that protects the detail page but leaks all descriptions through an export still leaks data. Write down whether approvers may read every request or only approve known targets; the sample\'s read endpoint intentionally remains owner-only.', es: 'Las listas, las exportaciones, las búsquedas, los conteos y los recursos anidados necesitan el mismo cuidado que una lectura individual. Un sistema que protege la página de detalle pero filtra todas las descripciones por una exportación igual filtra datos. Dejá escrito si los aprobadores pueden leer todas las solicitudes o solo aprobar destinos conocidos; el endpoint de lectura del ejemplo queda, a propósito, solo para el dueño.' }, { en: 'Check every route that can reveal or change the protected fact.', es: 'Verificá cada ruta que puede revelar o cambiar el hecho protegido.' })
  ], { en: 'Select Alice, Bob or the other tenant, then choose a row. Which predicate changes the result?', es: 'Elegí a Alice, a Bob o el otro tenant, y después elegí una fila. ¿Qué predicado cambia el resultado?' }, [
    Q({ en: 'What fixes an IDOR in this example?', es: '¿Qué arregla un IDOR en este ejemplo?' }, [{ en: 'Making IDs longer only', es: 'Solo hacer más largos los IDs' }, { en: 'Constraining the query with validated tenant and owner', es: 'Restringir la consulta con el tenant y el dueño validados' }, { en: 'Hiding the request ID in Angular', es: 'Ocultar el ID de la solicitud en Angular' }], 1, { en: 'The decisive control is object-level policy, independent of identifier guessability.', es: 'El control decisivo es la política a nivel de objeto, independiente de lo fácil que sea adivinar el identificador.' }),
    Q({ en: 'Where should owner_oid come from?', es: '¿De dónde tiene que salir owner_oid?' }, [{ en: 'The accepted API principal', es: 'Del principal aceptado de la API' }, { en: 'A hidden HTML field', es: 'De un campo oculto del HTML' }, { en: 'An owner parameter chosen by the caller', es: 'De un parámetro de dueño que elige quien llama' }], 0, { en: 'A caller must not assert the identity used to authorize their own request.', es: 'Quien llama no puede afirmar la identidad que se usa para autorizar su propio pedido.' }),
    Q({ en: 'Does protecting GET by ID protect an export automatically?', es: '¿Proteger el GET por ID protege también una exportación?' }, [{ en: 'Yes, if both use the same database', es: 'Sí, si los dos usan la misma base de datos' }, { en: 'Yes, if both require sign-in', es: 'Sí, si los dos exigen iniciar sesión' }, { en: 'No, each data path must enforce equivalent constraints', es: 'No, cada camino a los datos tiene que aplicar restricciones equivalentes' }], 2, { en: 'A separate query can bypass the protection unless the policy also reaches it.', es: 'Una consulta aparte puede saltear la protección, salvo que la política también la alcance.' })
  ], lab('owner', { en: 'Alice and Bob request the same ID. Will equal scopes produce equal results?', es: 'Alice y Bob piden el mismo ID. ¿Los mismos scopes van a dar los mismos resultados?' }, { en: 'Alice reading 42: 404. Bob reading 42: 200.', es: 'Alice leyendo la 42: 404. Bob leyendo la 42: 200.' }, { en: 'The exercise covers this endpoint. Inventory lists, exports and writes before claiming application-wide object isolation.', es: 'El ejercicio cubre este endpoint. Inventariá listas, exportaciones y escrituras antes de afirmar que toda la aplicación aísla los objetos.' }), 'object-auth');

  add(4, 'postgres-identity', { en: 'PostgreSQL authenticates the API', es: 'PostgreSQL autentica a la API' }, { en: 'Database authentication and end-user authorization are separate layers.', es: 'La autenticación de la base de datos y la autorización del usuario final son capas separadas.' }, 'database', [
    F({ en: 'The connection has its own principal', es: 'La conexión tiene su propio principal' }, { en: 'Spring obtains a JDBC connection as app_runtime. PostgreSQL authenticates that role using its configured mechanism; the local kit uses a deliberately local password over the isolated Compose network. There is no database port published on the host. Production needs secret management, encrypted transport and environment-specific database authentication.', es: 'Spring obtiene una conexión JDBC como app_runtime. PostgreSQL autentica ese rol con el mecanismo que tenga configurado; el kit local usa, a propósito, una contraseña local sobre la red aislada de Compose. No hay ningún puerto de la base de datos publicado en el host. Producción necesita manejo de secretos, transporte cifrado y una autenticación de base de datos propia de cada entorno.' }, { en: 'The API token is not automatically a database credential.', es: 'El token de la API no es, por sí solo, una credencial de la base de datos.' }),
    F({ en: 'Limit what the runtime role can do', es: 'Limitá lo que puede hacer el rol de ejecución' }, { en: 'The runtime role is neither superuser nor BYPASSRLS and does not own the table. It has SELECT and UPDATE on the status column, not permission to create schema objects or rewrite ownership. Migrations use a separate administrative identity. Row filtering complements these grants; it does not replace table and column privileges.', es: 'El rol de ejecución no es superusuario ni BYPASSRLS, y no es dueño de la tabla. Tiene SELECT, y UPDATE sobre la columna de estado, pero no permiso para crear objetos del esquema ni para reescribir la propiedad. Las migraciones usan otra identidad, de administración. El filtrado de filas complementa estos permisos; no reemplaza los privilegios sobre tablas y columnas.' }, { en: 'Separate migration power from application runtime power.', es: 'Separá el poder de las migraciones del poder de la aplicación en ejecución.' }),
    F({ en: 'Azure hosting is a separate choice', es: 'Alojar en Azure es otra elección' }, { en: 'Azure Database for PostgreSQL can support Microsoft Entra authentication with specific server configuration and identity mapping. That is a different database connection design and is not implemented by forwarding the purchase API token. Its resource, principal and lifetime requirements must be understood separately. The course\'s portable PostgreSQL baseline deliberately uses a normal database role.', es: 'Azure Database for PostgreSQL puede admitir autenticación con Microsoft Entra, con una configuración específica del servidor y un mapeo de identidades. Es otro diseño de conexión a la base de datos, y no se implementa reenviando el token de la API de compras. Sus requisitos de recurso, principal y vida útil hay que entenderlos aparte. La configuración base de PostgreSQL del curso, portable, usa a propósito un rol de base de datos común.' }, { en: 'Same identity provider does not mean same audience or connection protocol.', es: 'El mismo proveedor de identidad no implica la misma audiencia ni el mismo protocolo de conexión.' })
  ], { en: 'Switch the database role. Which role can bypass the intended row boundary?', es: 'Cambiá el rol de base de datos. ¿Qué rol puede saltear el límite de filas previsto?' }, [
    Q({ en: 'Does PostgreSQL automatically see Alice because Spring accepted her JWT?', es: '¿PostgreSQL ve a Alice por sí solo porque Spring aceptó su JWT?' }, [{ en: 'Yes, JDBC forwards the principal', es: 'Sí, JDBC reenvía el principal' }, { en: 'Yes, if the table contains oid', es: 'Sí, si la tabla tiene oid' }, { en: 'No, the connection authenticates its database role', es: 'No, la conexión autentica su rol de base de datos' }], 2, { en: 'The API must explicitly derive and apply user context to database operations.', es: 'La API tiene que obtener y aplicar de forma explícita el contexto del usuario en las operaciones de la base de datos.' }),
    Q({ en: 'Which identity should own schema migrations?', es: '¿Qué identidad tendría que ser dueña de las migraciones del esquema?' }, [{ en: 'The browser', es: 'El navegador' }, { en: 'A separate administrative identity', es: 'Una identidad de administración aparte' }, { en: 'Every signed-in user', es: 'Cada usuario que inicia sesión' }], 1, { en: 'Runtime access should be narrower than schema-administration access.', es: 'El acceso en ejecución tendría que ser más acotado que el de administración del esquema.' }),
    Q({ en: 'Can the same API access token be assumed valid for an Entra-enabled database?', es: '¿Se puede suponer que el mismo access token de la API vale para una base de datos con Entra habilitado?' }, [{ en: 'No, the database has a different resource contract', es: 'No, la base de datos tiene otro contrato de recurso' }, { en: 'Yes, both products are Microsoft-compatible', es: 'Sí, los dos productos son compatibles con Microsoft' }, { en: 'Yes, if the token is unexpired', es: 'Sí, si el token no venció' }], 0, { en: 'Audience and principal mapping must be appropriate for each resource independently.', es: 'La audiencia y el mapeo del principal tienen que ser los adecuados para cada recurso, por separado.' })
  ], lab('database', { en: 'Which database principal is active? Can it rewrite owner_oid as freely as status?', es: '¿Qué principal de base de datos está activo? ¿Puede reescribir owner_oid con la misma libertad que status?' }, { en: 'Database principal app_runtime; owner_oid UPDATE is false and status UPDATE is true.', es: 'Principal de base de datos app_runtime; UPDATE de owner_oid es false y UPDATE de status es true.' }, { en: 'The runtime role is still part of the trusted application. Protecting the database connection and SQL construction remains necessary.', es: 'El rol de ejecución sigue siendo parte de la aplicación de confianza. Proteger la conexión a la base de datos y la construcción del SQL sigue siendo necesario.' }), 'postgres-auth');

  add(4, 'row-level-security', { en: 'Row-level security as a second boundary', es: 'Row-level security como segundo límite' }, { en: 'Let the database filter rows, and understand who can bypass the filter.', es: 'Dejá que la base de datos filtre filas, y entendé quién puede saltear el filtro.' }, 'rows', [
    F({ en: 'A policy on the table', es: 'Una política sobre la tabla' }, { en: 'PostgreSQL row-level security evaluates a policy for ordinary row access. Our policy requires the tenant context to match and either the owner to match or the approver flag to be true. An unscoped SELECT under Alice\'s context can therefore still return only Alice\'s permitted rows. The API also includes predicates so its endpoint policy stays readable.', es: 'El row-level security de PostgreSQL evalúa una política para el acceso común a las filas. Nuestra política exige que coincida el contexto de tenant y, además, que coincida el dueño o que la marca de aprobador sea verdadera. Por eso, un SELECT sin filtros bajo el contexto de Alice igual puede devolver solo las filas que Alice tiene permitidas. La API también incluye predicados, para que la política de su endpoint se pueda leer.' }, { en: 'RLS can protect against a missing predicate; test that exact failure.', es: 'RLS puede proteger contra un predicado que falta; probá exactamente esa falla.' }),
    F({ en: 'The database role matters', es: 'El rol de base de datos importa' }, { en: 'A table owner normally bypasses RLS unless forced, and superusers and roles with BYPASSRLS bypass it. The sample enables and forces RLS and gives the runtime a separate, restricted role. Using the administrative connection to test a policy can produce a misleading result because that identity has powers the API must never use.', es: 'El dueño de una tabla normalmente saltea RLS salvo que se lo fuerce, y los superusuarios y los roles con BYPASSRLS lo saltean. El ejemplo habilita y fuerza RLS, y le da a la ejecución un rol aparte y restringido. Usar la conexión de administración para probar una política puede dar un resultado engañoso, porque esa identidad tiene poderes que la API nunca tiene que usar.' }, { en: 'Test policies as the runtime role, not as the migration administrator.', es: 'Probá las políticas como el rol de ejecución, no como el administrador de migraciones.' }),
    F({ en: 'Context is trusted application input', es: 'El contexto es una entrada de confianza de la aplicación' }, { en: 'The policy reads transaction-local settings established by Spring. Those strings are not cryptographic proof to PostgreSQL: an application with arbitrary SQL execution could set them differently. Parameterized queries and a trusted API remain essential. For writes, USING determines eligible existing rows and WITH CHECK constrains resulting rows; the sample also restricts writable columns.', es: 'La política lee settings locales de la transacción que fija Spring. Para PostgreSQL, esos textos no son una prueba criptográfica: una aplicación que pudiera ejecutar cualquier SQL podría fijarlos de otra manera. Las consultas parametrizadas y una API de confianza siguen siendo esenciales. En las escrituras, USING determina qué filas existentes califican y WITH CHECK restringe las filas que resultan; el ejemplo además restringe las columnas que se pueden escribir.' }, { en: 'RLS here is defense in depth, not isolation from a compromised API.', es: 'Acá RLS es defensa en profundidad, no aislamiento frente a una API comprometida.' })
  ], { en: 'Change the caller and tenant. Then compare runtime access with privileged database access.', es: 'Cambiá quién llama y el tenant. Después compará el acceso en ejecución con el acceso privilegiado a la base de datos.' }, [
    Q({ en: 'Why test an unfiltered SELECT as app_runtime?', es: '¿Por qué probar un SELECT sin filtros como app_runtime?' }, [{ en: 'To establish that RLS filters even a missing WHERE predicate', es: 'Para establecer que RLS filtra aunque falte el predicado WHERE' }, { en: 'To prove the API cannot be compromised', es: 'Para probar que la API no se puede comprometer' }, { en: 'To prove MFA occurred', es: 'Para probar que hubo MFA' }], 0, { en: 'That observation directly tests the additional database boundary.', es: 'Esa observación prueba directamente el límite adicional de la base de datos.' }),
    Q({ en: 'Can a superuser bypass this row policy?', es: '¿Un superusuario puede saltear esta política de filas?' }, [{ en: 'No, FORCE applies to every possible role', es: 'No, FORCE se aplica a cualquier rol posible' }, { en: 'Yes', es: 'Sí' }, { en: 'Only if Angular grants a role', es: 'Solo si Angular otorga un rol' }], 1, { en: 'Superuser and BYPASSRLS powers remain privileged escape routes.', es: 'Los poderes de superusuario y de BYPASSRLS siguen siendo vías de escape privilegiadas.' }),
    Q({ en: 'Does setting app.subject cryptographically authenticate Alice to PostgreSQL?', es: '¿Fijar app.subject autentica criptográficamente a Alice ante PostgreSQL?' }, [{ en: 'Yes, because the setting has a name', es: 'Sí, porque el setting tiene un nombre' }, { en: 'Yes, if it uses a UUID', es: 'Sí, si usa un UUID' }, { en: 'No, PostgreSQL trusts the application setting it', es: 'No, PostgreSQL confía en la aplicación que lo fija' }], 2, { en: 'The settings are context supplied by trusted code; they do not independently verify an Entra token.', es: 'Los settings son contexto que pone código de confianza; no verifican por su cuenta un token de Entra.' })
  ], lab('rls', { en: 'What should an unfiltered query return with no context, then Alice\'s context?', es: '¿Qué tendría que devolver una consulta sin filtros sin contexto, y después con el contexto de Alice?' }, { en: 'Zero rows, then row 41 only, while using the nonprivileged runtime role.', es: 'Cero filas, y después solo la fila 41, usando el rol de ejecución sin privilegios.' }, { en: 'The context is set by trusted application code. SQL injection or a compromised API remains outside this guarantee.', es: 'El contexto lo fija el código de confianza de la aplicación. Una inyección de SQL o una API comprometida quedan fuera de esta garantía.' }), 'rls');

  add(4, 'transactions-and-pools', { en: 'Transactions, pools and races', es: 'Transacciones, pools y carreras' }, { en: 'Authorization must survive connection reuse and concurrent requests.', es: 'La autorización tiene que resistir la reutilización de conexiones y los pedidos concurrentes.' }, 'database', [
    F({ en: 'A pool reuses physical connections', es: 'Un pool reutiliza conexiones físicas' }, { en: 'Connection pools make database access efficient by reusing connections across requests. A session-wide setting for Alice could remain when Bob later borrows that connection. Spring establishes the context inside the same transaction as the query using set_config with the local flag true. On transaction completion, that local setting no longer authorizes the next transaction.', es: 'Los pools de conexiones hacen eficiente el acceso a la base de datos reutilizando conexiones entre pedidos. Un setting de sesión para Alice podría quedar ahí cuando después Bob toma prestada esa conexión. Spring fija el contexto dentro de la misma transacción que la consulta, con set_config y la marca local en true. Cuando la transacción termina, ese setting local ya no autoriza la próxima transacción.' }, { en: 'The lifetime of identity context must match the transaction that uses it.', es: 'La vida del contexto de identidad tiene que coincidir con la transacción que lo usa.' }),
    F({ en: 'Check and change together', es: 'Verificá y cambiá a la vez' }, { en: 'A separate read of PENDING followed by an unconditional update invites a race: two callers can both observe the old state. The sample uses one UPDATE with tenant, not-owner and PENDING predicates. Under the normal PostgreSQL behavior used here, concurrent attempts cannot both change the same row from pending to approved. One succeeds; the other matches no eligible row.', es: 'Leer PENDING por separado y después hacer un update sin condiciones invita a una carrera: dos llamadas pueden ver las dos el estado viejo. El ejemplo usa un solo UPDATE con predicados de tenant, de no ser el dueño y de PENDING. Con el comportamiento normal de PostgreSQL que se usa acá, dos intentos concurrentes no pueden pasar los dos la misma fila de pendiente a aprobada. Uno lo logra; el otro no encuentra ninguna fila que califique.' }, { en: 'Put mutable authorization conditions into the atomic state transition.', es: 'Poné las condiciones de autorización que cambian dentro de la transición de estado atómica.' }),
    F({ en: 'Define the boundary of the transaction', es: 'Definí el límite de la transacción' }, { en: 'The SQL update and its row context share a transaction. Sending an email or charging a card would add an external effect that a database rollback cannot automatically undo. A real approval service needs an explicit strategy such as a transactional outbox, idempotency and retry policy. A successful row transition does not prove exactly-once business delivery.', es: 'El update de SQL y el contexto de su fila comparten una transacción. Mandar un email o cobrar con una tarjeta sumaría un efecto externo que un rollback de la base de datos no puede deshacer por sí solo. Un servicio de aprobación real necesita una estrategia explícita, como un transactional outbox, idempotencia y una política de reintentos. Que una fila cambie bien de estado no prueba que el negocio entregue el efecto exactamente una vez.' }, { en: 'Database atomicity ends at the database transaction boundary.', es: 'La atomicidad de la base de datos termina en el límite de la transacción de la base de datos.' })
  ], { en: 'Switch between a transaction-local and a session-lived context. Which identity would the next borrower inherit?', es: 'Alterná entre un contexto local de la transacción y uno que dura toda la sesión. ¿Qué identidad heredaría el próximo que tome prestada la conexión?' }, [
    Q({ en: 'Which setting lifetime fits a pooled request transaction?', es: '¿Qué duración del setting le sirve a la transacción de un pedido con pool?' }, [{ en: 'Permanent database setting', es: 'Setting permanente de la base de datos' }, { en: 'Transaction-local context', es: 'Contexto local de la transacción' }, { en: 'A browser localStorage flag', es: 'Una marca en el localStorage del navegador' }], 1, { en: 'The context must be cleared before a different request reuses the connection.', es: 'El contexto se tiene que limpiar antes de que otro pedido reutilice la conexión.' }),
    Q({ en: 'Why put status=PENDING in the UPDATE?', es: '¿Por qué poner status=PENDING en el UPDATE?' }, [{ en: 'It combines eligibility and mutation atomically', es: 'Combina de forma atómica la elegibilidad y el cambio' }, { en: 'It makes every network retry safe', es: 'Hace seguro cualquier reintento de red' }, { en: 'It guarantees an email is sent once', es: 'Garantiza que un email se mande una sola vez' }], 0, { en: 'The database can serialize the competing changes and re-evaluate the condition.', es: 'La base de datos puede serializar los cambios que compiten y volver a evaluar la condición.' }),
    Q({ en: 'Does one committed update guarantee one external notification?', es: '¿Un update confirmado garantiza una sola notificación externa?' }, [{ en: 'Yes, JDBC handles it', es: 'Sí, lo maneja JDBC' }, { en: 'Yes, if the token is valid', es: 'Sí, si el token es válido' }, { en: 'No, external effects need their own delivery design', es: 'No, los efectos externos necesitan su propio diseño de entrega' }], 2, { en: 'The row transaction cannot atomically control an unrelated external service by itself.', es: 'La transacción de la fila no puede controlar sola, de forma atómica, un servicio externo que no tiene nada que ver.' })
  ], [
    S({ en: 'Predict context reuse', es: 'Predecí la reutilización del contexto' }, { en: 'Predict the visible row count after committing Alice\'s transaction on the same SQL connection.', es: 'Predecí cuántas filas se ven después de confirmar la transacción de Alice en la misma conexión SQL.' }, { en: 'Zero visible rows without fresh context.', es: 'Cero filas visibles sin un contexto nuevo.' }),
    S({ en: 'Observe connection and request isolation', es: 'Observá el aislamiento de la conexión y de los pedidos' }, { en: 'The scenario checks the same database session before and after COMMIT and alternates Alice and Bob API requests.', es: 'El escenario verifica la misma sesión de la base de datos antes y después del COMMIT, y alterna pedidos a la API de Alice y de Bob.' }, { en: 'Context resets after commit; Alice receives 200 and Bob receives 404 for request 41.', es: 'El contexto se limpia después del commit; Alice recibe 200 y Bob recibe 404 para la solicitud 41.' }, 'node lab.mjs pool'),
    S({ en: 'Race two approvals', es: 'Poné a competir dos aprobaciones' }, { en: 'This scenario resets only fixture row 42 to PENDING, sends concurrent approvals and restores it after the assertions. It does not reset other course resources.', es: 'Este escenario vuelve a PENDING solo la fila 42 del fixture, manda aprobaciones concurrentes y la restaura después de las aserciones. No restaura otros recursos del curso.' }, { en: 'Exactly one 200 and one 404; PostgreSQL stores APPROVED before the fixture reset.', es: 'Exactamente un 200 y un 404; PostgreSQL guarda APPROVED antes de que se restaure el fixture.' }, 'node lab.mjs atomic'),
    S({ en: 'Extend the design on paper', es: 'Extendé el diseño en papel' }, { en: 'Add an email notification to the approval. Describe the crash point between committing the row and sending the email.', es: 'Agregale a la aprobación una notificación por email. Describí el punto de caída entre confirmar la fila y mandar el email.' }, { en: 'A proposed outbox and idempotency boundary, with a stated limit on external effects.', es: 'Un outbox y un límite de idempotencia propuestos, con un límite explícito sobre los efectos externos.' })
  ], 'transactions');

  add(5, 'token-lifecycle', { en: 'Expiry, renewal and sign-out', es: 'Vencimiento, renovación y cierre de sesión' }, { en: 'A token is a time-bounded snapshot, not a live directory query.', es: 'Un token es una foto con límite de tiempo, no una consulta en vivo al directorio.' }, 'lifecycle', [
    F({ en: 'The token has a validity interval', es: 'El token tiene un intervalo de validez' }, { en: 'The resource server checks expiration and not-before times, with bounded clock skew. Do not hard-code one universal Entra access-token lifetime into business policy. Issuance conditions and token types can differ. The fixture uses short-lived tokens to make the mechanism visible; its expiry values are teaching data, not evidence of tenant defaults.', es: 'El resource server verifica los tiempos de vencimiento y de no-antes, con un desfasaje de reloj acotado. No fijes en la política de negocio una única duración universal de los access tokens de Entra. Las condiciones de emisión y los tipos de token pueden variar. El fixture usa tokens de vida corta para que el mecanismo se vea; sus valores de vencimiento son datos de enseñanza, no evidencia de los valores por defecto del tenant.' }, { en: 'Read validity as a checked interval, not a promised constant.', es: 'Leé la validez como un intervalo que se verifica, no como una constante prometida.' }),
    F({ en: 'A changed role meets an older token', es: 'Un rol que cambió se encuentra con un token anterior' }, { en: 'When an administrator removes Approver, an already issued token may still carry it. A resource server doing local JWT validation does not automatically re-read every assignment on every request. MSAL renewal can obtain newer evidence. Systems needing faster permission withdrawal must explicitly design and test additional enforcement rather than assume the token is a live pointer.', es: 'Cuando un administrador quita Approver, un token ya emitido todavía puede traerlo. Un resource server que valida el JWT localmente no vuelve a leer todas las asignaciones en cada pedido. La renovación de MSAL puede obtener evidencia más nueva. Los sistemas que necesitan retirar permisos más rápido tienen que diseñar y probar de forma explícita controles adicionales, en lugar de suponer que el token es un puntero en vivo.' }, { en: 'Assignment time, issuance time and request time are different clocks.', es: 'El momento de la asignación, el de la emisión y el del pedido son relojes distintos.' }),
    F({ en: 'Sign-out has more than one surface', es: 'Cerrar sesión tiene más de una superficie' }, { en: 'Clearing the application cache, ending the identity-provider session and preventing replay of a previously issued access token are different operations. Continuous access evaluation exists for supported resources and scenarios; a custom Spring API does not acquire all of that behavior merely by validating a JWT. The sample implements no claims-challenge or CAE integration.', es: 'Limpiar la caché de la aplicación, terminar la sesión en el proveedor de identidad e impedir que se reutilice un access token ya emitido son operaciones distintas. La continuous access evaluation existe para algunos recursos y escenarios admitidos; una API Spring propia no adquiere todo ese comportamiento solo por validar un JWT. El ejemplo no implementa claims challenge ni integración con CAE.' }, { en: 'Do not promise instant revocation from a local sign-out button.', es: 'No prometas una revocación instantánea por un botón local de cierre de sesión.' })
  ], { en: 'Move the request time across expiry. Then remove a role after token issuance and compare the two events.', es: 'Mové el momento del pedido más allá del vencimiento. Después quitá un rol cuando el token ya se emitió y compará los dos hechos.' }, [
    Q({ en: 'A JWT was issued before a role was removed. What should you assume?', es: 'Un JWT se emitió antes de que se quitara un rol. ¿Qué tenés que suponer?' }, [{ en: 'Its claims were rewritten remotely', es: 'Que sus claims se reescribieron a distancia' }, { en: 'The API reads the directory every time', es: 'Que la API lee el directorio cada vez' }, { en: 'It may still contain the old role until other controls intervene', es: 'Que todavía puede tener el rol viejo hasta que intervengan otros controles' }], 2, { en: 'Token freshness and revocation behavior need explicit handling.', es: 'La vigencia de los tokens y cómo se revocan necesitan un tratamiento explícito.' }),
    Q({ en: 'What does the local sign-out button guarantee about a copied access token?', es: '¿Qué garantiza el botón local de cierre de sesión sobre un access token copiado?' }, [{ en: 'It is immediately invalid everywhere', es: 'Que queda inválido en el momento, en todos lados' }, { en: 'No universal immediate-revocation guarantee', es: 'Ninguna garantía universal de revocación inmediata' }, { en: 'It stops working as soon as the original browser tab closes', es: 'Que deja de funcionar en cuanto se cierra la pestaña original' }], 1, { en: 'Local cache removal does not itself change a signed token already held elsewhere.', es: 'Borrar la caché local no cambia, por sí solo, un token firmado que alguien ya tiene en otro lado.' }),
    Q({ en: 'What does the expired fixture test establish?', es: '¿Qué establece la prueba del fixture vencido?' }, [{ en: 'Spring enforces the configured timestamp check', es: 'Que Spring aplica la verificación de tiempo configurada' }, { en: 'The tenant\'s exact lifetime policy', es: 'La política exacta de duración del tenant' }, { en: 'CAE is active', es: 'Que CAE está activo' }], 0, { en: 'The fixture checks the local resource-server implementation, not tenant lifecycle behavior.', es: 'El fixture verifica la implementación local del resource server, no el comportamiento del ciclo de vida del tenant.' })
  ], lab('time', { en: 'What happens when exp is in the past or nbf is sufficiently in the future?', es: '¿Qué pasa cuando exp está en el pasado o nbf está lo bastante en el futuro?' }, { en: 'Both credentials receive 401, beyond the decoder\'s clock-skew allowance.', es: 'Las dos credenciales reciben 401, más allá del margen de desfasaje de reloj del decoder.' }, { en: 'These tests do not establish role-revocation latency or CAE support in a tenant.', es: 'Estas pruebas no establecen la demora en la revocación de roles ni el soporte de CAE en un tenant.' }), 'lifetime');

  add(5, 'connect-a-real-tenant', { en: 'Connect a real Entra tenant', es: 'Conectá un tenant real de Entra' }, { en: 'Replace the source of identity evidence while preserving the application policy.', es: 'Reemplazá la fuente de la evidencia de identidad y conservá la política de la aplicación.' }, 'registrations', [
    F({ en: 'Switch trust deliberately', es: 'Cambiá la confianza a propósito' }, { en: 'The tenant workbook configures AUTH_MODE=entra, a real tenant ID and the two application client IDs. Spring then uses the fixed tenant v2 issuer and its discovered keys; the local fixture key is no longer trusted. The frontend configuration switches to Entra mode and refuses to proceed if the API reports a different mode. Never publish the fixture token service.', es: 'El recorrido del tenant configura AUTH_MODE=entra, un tenant ID real y los client IDs de las dos aplicaciones. Desde ahí, Spring usa el issuer v2 fijo del tenant y sus claves descubiertas; la clave local del fixture deja de ser de confianza. La configuración del frontend pasa a modo Entra y se niega a seguir si la API informa otro modo. Nunca publiques el servicio de tokens del fixture.' }, { en: 'A test issuer is a different trust root, not a fallback for failed sign-in.', es: 'Un emisor de prueba es otra raíz de confianza, no un respaldo para cuando falla el inicio de sesión.' }),
    F({ en: 'Provision the data deliberately', es: 'Cargá los datos a propósito' }, { en: 'Real users have different oid values from Alice and Bob in the fixture. The workbook seeds invented records under validated tenant user IDs obtained from the directory. It does not assign record ownership from an email submitted by the browser. The user without Approver should read their own request; the assigned approver should approve somebody else\'s pending request.', es: 'Los usuarios reales tienen valores de oid distintos de los de Alice y Bob en el fixture. El recorrido carga registros inventados con IDs de usuario del tenant validados, obtenidos del directorio. No asigna la propiedad de los registros a partir de un email que manda el navegador. El usuario sin Approver tendría que leer su propia solicitud; el aprobador asignado tendría que aprobar la solicitud pendiente de otra persona.' }, { en: 'A valid identity needs an explicit relationship to application data.', es: 'Una identidad válida necesita una relación explícita con los datos de la aplicación.' }),
    F({ en: 'Record only what you observed', es: 'Anotá solo lo que observaste' }, { en: 'Observe successful sign-in, a token acquired for the API, an own-record read, a role denial and a permitted approval. Mark each result in TENANT-EVIDENCE.txt. If policy prevents registration or consent, use the case study and record the missing observation. Tenant configuration, licenses and organizational controls can change which administrative actions are available.', es: 'Observá un inicio de sesión exitoso, un token obtenido para la API, la lectura de un registro propio, un rechazo por rol y una aprobación permitida. Marcá cada resultado en TENANT-EVIDENCE.txt. Si la política impide el registro o el consentimiento, usá el caso de estudio y anotá la observación que falta. La configuración del tenant, las licencias y los controles de la organización pueden cambiar qué acciones de administración están disponibles.' }, { en: 'An unexecuted tenant exercise stays unverified.', es: 'Un ejercicio del tenant que no se ejecutó queda sin verificar.' })
  ], { en: 'Compare fixture and Entra trust roots. Which private key could produce a token the API accepts now?', es: 'Compará las raíces de confianza del fixture y de Entra. ¿Qué clave privada podría producir ahora un token que la API acepte?' }, [
    Q({ en: 'Should a failing Entra sign-in fall back to the local token dispenser?', es: 'Si falla un inicio de sesión en Entra, ¿se tendría que recurrir al emisor local de tokens?' }, [{ en: 'No, that would change the trust boundary', es: 'No, eso cambiaría el límite de confianza' }, { en: 'Yes, to keep the demonstration working', es: 'Sí, para que la demostración siga funcionando' }, { en: 'Yes, if the user name matches', es: 'Sí, si coincide el nombre de usuario' }], 0, { en: 'Fixture and Entra modes are deliberately separate, not failover mechanisms.', es: 'Los modos fixture y Entra están separados a propósito; no son mecanismos de respaldo.' }),
    Q({ en: 'Why can a real user receive 404 on fixture row 41?', es: '¿Por qué un usuario real puede recibir 404 para la fila 41 del fixture?' }, [{ en: 'Entra cannot issue access tokens', es: 'Entra no puede emitir access tokens' }, { en: 'The record\'s fixture owner is a different oid', es: 'El dueño de ese registro en el fixture es otro oid' }, { en: 'Angular always changes the audience', es: 'Angular siempre cambia la audiencia' }], 1, { en: 'Authentication does not automatically transfer fixture data ownership.', es: 'La autenticación no transfiere por sí sola la propiedad de los datos del fixture.' }),
    Q({ en: 'What proves the actual tenant role assignment worked?', es: '¿Qué prueba que la asignación de rol real del tenant funcionó?' }, [{ en: 'The local roles test alone', es: 'La prueba local de roles, sola' }, { en: 'A diagram showing Approver', es: 'Un diagrama que muestra Approver' }, { en: 'A recorded tenant-issued request with the expected authorization result', es: 'Un pedido anotado con un token emitido por el tenant y el resultado de autorización esperado' }], 2, { en: 'The tenant route needs its own direct evidence.', es: 'El recorrido del tenant necesita su propia evidencia directa.' })
  ], study({ en: 'Predict how the first real user\'s oid differs from the seeded Alice value.', es: 'Predecí en qué se diferencia el oid del primer usuario real del valor de Alice que se cargó.' }, { en: 'Complete TENANT.md sections E and G. Recreate the API in Entra mode, provision invented rows for two practice identities and execute the acceptance matrix. Use TENANT.md in the lab kit. Use a practice tenant and invented purchase requests.', es: 'Completá las secciones E y G de TENANT.md. Volvé a crear la API en modo Entra, cargá filas inventadas para dos identidades de práctica y ejecutá la matriz de aceptación. Usá TENANT.md del kit. Usá un tenant de práctica y solicitudes de compra inventadas.' }, { en: 'Own read succeeds, missing role is denied, permitted non-owner approval succeeds, fixture credentials are rejected.', es: 'La lectura propia sale bien, el rol que falta se rechaza, la aprobación permitida de alguien que no es el dueño sale bien y las credenciales del fixture se rechazan.' }, { en: 'A valid Entra token gets 404 for row 41. Given its different oid, explain why changing the API to accept arbitrary owner IDs would be the wrong fix.', es: 'Un token válido de Entra recibe 404 para la fila 41. Teniendo en cuenta que su oid es otro, explicá por qué cambiar la API para que acepte cualquier ID de dueño sería el arreglo equivocado.' }), 'registration', 'tenant');

  add(5, 'workloads-and-downstream-apis', { en: 'Users, workloads and downstream APIs', es: 'Usuarios, workloads y APIs de más abajo' }, { en: 'Choose the principal before choosing the grant.', es: 'Elegí el principal antes de elegir el grant.' }, 'tokens', [
    F({ en: 'A background job has no signed-in user', es: 'Un proceso en segundo plano no tiene un usuario con la sesión iniciada' }, { en: 'Client credentials obtains access as an application using a confidential-client credential or another supported workload mechanism. Application permissions and administrative grant govern that access. It does not invent a human actor. The SPA must not run this flow with an embedded secret. Our user-oriented endpoints intentionally require delegated scopes and reject a roles-only fixture.', es: 'Client credentials obtiene acceso como una aplicación, con la credencial de un cliente confidencial o con otro mecanismo de workload admitido. Los permisos de aplicación y el otorgamiento de un administrador gobiernan ese acceso. No inventa un actor humano. La SPA no tiene que ejecutar este flujo con un secreto incrustado. Nuestros endpoints orientados a usuarios exigen, a propósito, scopes delegados y rechazan un fixture que solo tiene roles.' }, { en: 'Application access and delegated user access are different policies.', es: 'El acceso de una aplicación y el acceso delegado de un usuario son políticas distintas.' }),
    F({ en: 'Another API means another audience', es: 'Otra API quiere decir otra audiencia' }, { en: 'Suppose Spring must read Microsoft Graph on behalf of the user. The incoming purchase API access token is intended for Spring, not Graph. A properly configured confidential middle tier can use the on-behalf-of flow to request downstream delegated access. Consent and downstream permission requirements still apply. Simply forwarding the incoming token is not a valid audience conversion.', es: 'Supongamos que Spring tiene que leer Microsoft Graph en nombre del usuario. El access token de la API de compras que entra está destinado a Spring, no a Graph. Una capa intermedia confidencial bien configurada puede usar el flujo on-behalf-of para pedir acceso delegado hacia abajo. El consentimiento y los requisitos de permisos de más abajo siguen valiendo. Reenviar el token que entra no es una conversión de audiencia válida.' }, { en: 'A token does not become portable because one service calls another.', es: 'Un token no se vuelve portable porque un servicio llame a otro.' }),
    F({ en: 'Keep the extension outside the baseline', es: 'Dejá la extensión fuera de la configuración base' }, { en: 'The sample does not call Graph, implement OBO or accept workload approval. Those are design exercises with their own threat models. If a nightly job must close stale requests, define its permission, allowed tenant, audit identity and record rules separately. A broad OR between user scopes and application roles is usually too vague to review safely.', es: 'El ejemplo no llama a Graph, no implementa OBO ni acepta aprobaciones de un workload. Son ejercicios de diseño con sus propios modelos de amenazas. Si un proceso nocturno tiene que cerrar solicitudes viejas, definí por separado su permiso, el tenant permitido, la identidad de auditoría y las reglas de los registros. Un OR amplio entre scopes de usuario y roles de aplicación suele ser demasiado vago para revisarlo de forma segura.' }, { en: 'Extend the contract deliberately and test both allowed and denied callers.', es: 'Extendé el contrato a propósito y probá tanto a quienes se permite llamar como a quienes se rechaza.' })
  ], { en: 'Switch from API token to Graph token or app-only token. Which recipient and policy should accept each?', es: 'Cambiá del token de la API al token de Graph o a un token app-only. ¿Qué destinatario y qué política tendrían que aceptar cada uno?' }, [
    Q({ en: 'A scheduled daemon runs with client credentials. Who is acting?', es: 'Un daemon programado corre con client credentials. ¿Quién está actuando?' }, [{ en: 'The last user who signed in', es: 'El último usuario que inició sesión' }, { en: 'The application identity', es: 'La identidad de la aplicación' }, { en: 'Every user in the tenant', es: 'Cada usuario del tenant' }], 1, { en: 'There is no signed-in user in that grant.', es: 'En ese grant no hay ningún usuario con la sesión iniciada.' }),
    Q({ en: 'Spring needs delegated Graph access. Can it forward the purchase API token?', es: 'Spring necesita acceso delegado a Graph. ¿Puede reenviar el token de la API de compras?' }, [{ en: 'No, it needs a token intended for the downstream resource', es: 'No, necesita un token destinado al recurso de más abajo' }, { en: 'Yes, if Microsoft signed it', es: 'Sí, si lo firmó Microsoft' }, { en: 'Yes, if it copies the same scopes', es: 'Sí, si copia los mismos scopes' }], 0, { en: 'Audience is recipient-specific. OBO is a distinct exchange with its own requirements.', es: 'La audiencia es propia de cada destinatario. OBO es un canje distinto, con sus propios requisitos.' }),
    Q({ en: 'What does the sample prove about OBO?', es: '¿Qué prueba el ejemplo sobre OBO?' }, [{ en: 'A successful downstream Graph request', es: 'Un pedido exitoso a Graph, más abajo' }, { en: 'Administrator consent for Graph', es: 'El consentimiento de un administrador para Graph' }, { en: 'Nothing executed; the lesson is a design extension', es: 'Nada se ejecutó; la lección es una extensión de diseño' }], 2, { en: 'The implemented lab verifies the user endpoint rejects the wrong access model.', es: 'El lab implementado verifica que el endpoint de usuario rechaza el modelo de acceso equivocado.' })
  ], lab('delegation', { en: 'Why should a roles-only workload fail this user approval endpoint?', es: '¿Por qué un workload que solo tiene roles tendría que fallar en este endpoint de aprobación de usuarios?' }, { en: 'App-only token receives 403, while a mismatched client receives 401.', es: 'El token app-only recibe 403, y un cliente que no coincide recibe 401.' }, { en: 'This is not an OBO implementation. Design a separate permission and evidence plan for a background job or downstream call.', es: 'Esto no es una implementación de OBO. Diseñá un permiso y un plan de evidencia aparte para un proceso en segundo plano o una llamada hacia abajo.' }), 'obo');

  add(5, 'browser-threats-and-bff', { en: 'Browser threats and architecture choices', es: 'Amenazas en el navegador y decisiones de arquitectura' }, { en: 'Understand what CORS, PKCE and a BFF each change.', es: 'Entendé qué cambia cada uno: CORS, PKCE y un BFF.' }, 'boundaries', [
    F({ en: 'CORS is a browser cooperation rule', es: 'CORS es una regla de cooperación del navegador' }, { en: 'A cross-origin browser request may first send an OPTIONS preflight. Our API permits the exact local frontend origin, methods and Authorization header. CORS is not a substitute for token validation or authorization: a command-line caller can omit Origin entirely and still reach the API. It must face the same authentication and business checks.', es: 'Un pedido de navegador entre orígenes puede mandar primero un preflight OPTIONS. Nuestra API permite el origen exacto del frontend local, los métodos y el header Authorization. CORS no reemplaza la validación del token ni la autorización: alguien que llama desde la línea de comandos puede omitir Origin del todo y llegar igual a la API. Tiene que enfrentar las mismas verificaciones de autenticación y de negocio.' }, { en: 'An allowed origin is not an authenticated principal.', es: 'Un origen permitido no es un principal autenticado.' }),
    F({ en: 'Browser script is inside the user\'s session', es: 'El script del navegador está dentro de la sesión del usuario' }, { en: 'XSS can execute within the application origin and act with the session\'s powers. CSP, safe rendering, dependency maintenance and careful token handling reduce risk; PKCE does not solve malicious script execution. The sample uses bearer headers and no cookie login, which is why its API disables CSRF protection. Adding cookie authentication would change that decision.', es: 'Un XSS puede ejecutarse dentro del origen de la aplicación y actuar con los poderes de la sesión. Una CSP, un renderizado seguro, el mantenimiento de las dependencias y un manejo cuidadoso de los tokens reducen el riesgo; PKCE no resuelve la ejecución de scripts maliciosos. El ejemplo usa headers bearer y ningún login con cookie, y por eso su API deshabilita la protección CSRF. Agregar autenticación con cookies cambiaría esa decisión.' }, { en: 'A security setting is valid only under its stated architecture assumptions.', es: 'Una configuración de seguridad vale solo bajo los supuestos de arquitectura que declara.' }),
    F({ en: 'A backend for frontend moves the boundary', es: 'Un backend for frontend mueve el límite' }, { en: 'A BFF can keep OAuth tokens on the server and give the browser a Secure, HttpOnly session cookie with a deliberate SameSite and CSRF policy. That reduces direct exposure of tokens to browser code, while introducing session and server-side lifecycle responsibilities. XSS can still issue actions through an authenticated session. Choose the pattern based on the threat model and operational capacity.', es: 'Un BFF puede guardar los tokens de OAuth en el servidor y darle al navegador una cookie de sesión Secure y HttpOnly, con una política de SameSite y de CSRF deliberada. Eso reduce la exposición directa de los tokens al código del navegador, pero suma responsabilidades de sesión y de ciclo de vida del lado del servidor. Un XSS igual puede disparar acciones a través de una sesión autenticada. Elegí el patrón según el modelo de amenazas y la capacidad operativa.' }, { en: 'Moving a credential changes the risks; it does not remove authorization.', es: 'Mover una credencial cambia los riesgos; no elimina la autorización.' })
  ], { en: 'Block the browser origin, then imagine a non-browser client. Which checks remain necessary?', es: 'Bloqueá el origen del navegador, y después imaginá un cliente que no es un navegador. ¿Qué verificaciones siguen haciendo falta?' }, [
    Q({ en: 'A caller sends no Origin header. Should a valid token still be required?', es: 'Alguien llama sin header Origin. ¿Igual se tendría que exigir un token válido?' }, [{ en: 'Yes', es: 'Sí' }, { en: 'No, CORS already protected the API', es: 'No, CORS ya protegió la API' }, { en: 'Only for browsers', es: 'Solo para los navegadores' }], 0, { en: 'Non-browser callers do not rely on CORS. The resource boundary must stand independently.', es: 'Los que llaman sin navegador no dependen de CORS. El límite del recurso tiene que sostenerse por su cuenta.' }),
    Q({ en: 'Why is CSRF disabled in this sample API?', es: '¿Por qué está deshabilitado CSRF en la API del ejemplo?' }, [{ en: 'CSRF never affects Spring', es: 'CSRF nunca afecta a Spring' }, { en: 'Its authentication uses explicit bearer headers, without cookie login', es: 'Su autenticación usa headers bearer explícitos, sin login con cookie' }, { en: 'PKCE disables CSRF globally', es: 'PKCE deshabilita CSRF en todos lados' }], 1, { en: 'That choice depends on the credential delivery model and must be reconsidered for cookie sessions.', es: 'Esa elección depende del modelo de entrega de la credencial, y hay que reconsiderarla para las sesiones con cookies.' }),
    Q({ en: 'What does a BFF eliminate?', es: '¿Qué elimina un BFF?' }, [{ en: 'Every XSS consequence', es: 'Toda consecuencia de un XSS' }, { en: 'The need for API authorization', es: 'La necesidad de autorización en la API' }, { en: 'Neither of those; it changes token exposure and session design', es: 'Ninguna de esas cosas; cambia la exposición de los tokens y el diseño de la sesión' }], 2, { en: 'Server-side token custody does not make browser-origin actions harmless.', es: 'Que el servidor guarde los tokens no vuelve inofensivas las acciones desde el origen del navegador.' })
  ], lab('cors', { en: 'Will an allowed preflight make an unauthenticated read succeed?', es: '¿Un preflight permitido va a hacer que salga bien una lectura sin autenticación?' }, { en: 'Allowed preflight, then 401 without a token, 200 with Alice, and rejected foreign-origin preflight.', es: 'Preflight permitido, después 401 sin token, 200 con Alice, y rechazo del preflight de un origen ajeno.' }, { en: 'HTTP tests observe headers and statuses. Full browser behavior, CSP and production session design need separate validation.', es: 'Las pruebas HTTP observan headers y códigos de estado. El comportamiento completo del navegador, la CSP y el diseño de sesión de producción necesitan su propia validación.' }), 'browser');

  add(6, 'debug-without-leaking', { en: 'Debug without leaking credentials', es: 'Depurá sin filtrar credenciales' }, { en: 'Follow evidence in order instead of granting more power until the error disappears.', es: 'Seguí la evidencia en orden, en lugar de dar más poder hasta que desaparezca el error.' }, 'boundaries', [
    F({ en: 'Start with the failed hop', es: 'Empezá por el salto que falló' }, { en: 'Write the method, destination, status and a correlation ID. Did sign-in fail before returning to Angular? Did token acquisition fail? Did an OPTIONS request fail before the API call? Did the actual API reject authentication or operation authority? A network symptom at one hop is not a reason to relax a different hop\'s policy.', es: 'Escribí el método, el destino, el código de estado y un ID de correlación. ¿Falló el inicio de sesión antes de volver a Angular? ¿Falló la obtención del token? ¿Falló un pedido OPTIONS antes de la llamada a la API? ¿La llamada real a la API rechazó la autenticación o la authority de la operación? Un síntoma de red en un salto no es motivo para aflojar la política de otro salto.' }, { en: 'Locate the first failed boundary before changing configuration.', es: 'Ubicá el primer límite que falló antes de cambiar la configuración.' }),
    F({ en: 'Compare contracts, not secrets', es: 'Compará contratos, no secretos' }, { en: 'For a token rejection, compare expected issuer, audience, tenant, time and allowed client with safely inspected claim categories. Never paste a production credential into a support ticket. For a row denial, inspect the validated subject, tenant and relevant predicate under controlled access. Logs should avoid raw Authorization headers, cookies and unnecessary personal fields.', es: 'Ante el rechazo de un token, compará el issuer, la audiencia, el tenant, el tiempo y el cliente permitido que se esperan con las categorías de claims inspeccionadas de forma segura. Nunca pegues una credencial de producción en un ticket de soporte. Ante el rechazo de una fila, inspeccioná el sujeto validado, el tenant y el predicado que corresponde, con acceso controlado. Los logs tendrían que evitar los headers Authorization crudos, las cookies y los datos personales que no hacen falta.' }, { en: 'Collect enough evidence to explain the decision, not enough credentials to replay it.', es: 'Juntá evidencia suficiente para explicar la decisión, no credenciales suficientes para repetirla.' }),
    F({ en: 'Use a negative case to validate the fix', es: 'Usá un caso negativo para validar el arreglo' }, { en: 'If a wrong API audience caused 401, correct the configuration and keep a wrong-audience test that still fails. If an owner mismatch caused 404, provision the right record rather than removing the owner predicate. Every fix should restore the intended allowed path while preserving a nearby denied path. The lab matrix provides that discipline.', es: 'Si una audiencia de API equivocada causó un 401, corregí la configuración y conservá una prueba de audiencia equivocada que siga fallando. Si una discrepancia de dueño causó un 404, cargá el registro correcto en lugar de quitar el predicado del dueño. Cada arreglo tendría que restaurar el camino permitido previsto y conservar un camino rechazado cercano. La matriz del lab aporta esa disciplina.' }, { en: 'A fix is credible when the neighboring denial still works.', es: 'Un arreglo es creíble cuando el rechazo vecino sigue funcionando.' })
  ], { en: 'Choose the first failing boundary, then identify a safe piece of evidence that would confirm it.', es: 'Elegí el primer límite que falla, y después identificá una pieza de evidencia segura que lo confirmaría.' }, [
    Q({ en: 'An own-read bug disappears after removing owner filtering. Is that a good fix?', es: 'Un bug en la lectura propia desaparece al quitar el filtro por dueño. ¿Es un buen arreglo?' }, [{ en: 'Yes, if the demo is green', es: 'Sí, si la demo da verde' }, { en: 'No, it may have erased the data boundary', es: 'No, puede haber borrado el límite de los datos' }, { en: 'Yes, if sign-in still works', es: 'Sí, si el inicio de sesión sigue funcionando' }], 1, { en: 'The correct fix must preserve denial of somebody else\'s data.', es: 'El arreglo correcto tiene que seguir rechazando el acceso a los datos de otra persona.' }),
    Q({ en: 'What belongs in a diagnostic ticket?', es: '¿Qué va en un ticket de diagnóstico?' }, [{ en: 'The full bearer token', es: 'El bearer token completo' }, { en: 'A refresh token for reproduction', es: 'Un refresh token para reproducir el problema' }, { en: 'Sanitized request metadata and relevant mismatch categories', es: 'Metadatos del pedido saneados y las categorías de discrepancia que corresponden' }], 2, { en: 'Credentials should not become debugging artifacts.', es: 'Las credenciales no se tienen que convertir en material de depuración.' }),
    Q({ en: 'What should accompany an allowed-path fix?', es: '¿Qué tendría que acompañar el arreglo de un camino permitido?' }, [{ en: 'A nearby denied-path regression test', es: 'Una prueba de regresión de un camino rechazado cercano' }, { en: 'A broader role assignment for everyone', es: 'Una asignación de rol más amplia para todos' }, { en: 'A disabled audience validator', es: 'Un validador de audiencia deshabilitado' }], 0, { en: 'The denied case establishes that the security boundary survived the fix.', es: 'El caso rechazado establece que el límite de seguridad sobrevivió al arreglo.' })
  ], lab('audience', { en: 'Which single configuration concept explains a valid signature with an API rejection?', es: '¿Qué concepto de configuración, uno solo, explica una firma válida con un rechazo de la API?' }, { en: 'Wrong audience: 401. Correct fixture audience: 200.', es: 'Audiencia equivocada: 401. Audiencia correcta del fixture: 200.' }, { en: 'An audience fix must not widen acceptance to every token from the identity provider.', es: 'Un arreglo de audiencia no puede ampliar la aceptación a cualquier token del proveedor de identidad.' }), 'claims');

  add(6, 'review-the-design', { en: 'Review the whole design', es: 'Revisá el diseño completo' }, { en: 'Find the smallest counterexample that breaks an overbroad claim.', es: 'Encontrá el contraejemplo más chico que rompe una afirmación demasiado amplia.' }, 'policy', [
    F({ en: 'A deliberately weak proposal', es: 'Una propuesta débil a propósito' }, { en: 'A teammate proposes one registration, an Angular role guard, acceptance of any Microsoft-signed JWT, a caller-supplied owner email and a PostgreSQL admin connection. They describe this as authenticated end to end. Review each statement by asking what an attacker-controlled client can change and which independent component would reject the change.', es: 'Alguien del equipo propone un solo registro, un role guard en Angular, aceptar cualquier JWT firmado por Microsoft, un email de dueño que manda quien llama y una conexión de administrador a PostgreSQL. Lo describe como autenticado de punta a punta. Revisá cada afirmación preguntando qué puede cambiar un cliente controlado por un atacante y qué componente independiente rechazaría ese cambio.' }, { en: 'A confident architecture description is not a chain of evidence.', es: 'Una descripción de arquitectura segura de sí misma no es una cadena de evidencia.' }),
    F({ en: 'Repair the contract explicitly', es: 'Repará el contrato de forma explícita' }, { en: 'Specify a public SPA and a separate API resource, a fixed single-tenant issuer, the API audience, permitted client, required delegated scopes and app role, stable tenant-plus-object identities, parameterized row constraints and a restricted database role. The choice of AND, exact audience and record predicate should be visible to a reviewer without guessing.', es: 'Especificá una SPA pública y un recurso de API aparte, un issuer fijo de un solo tenant, la audiencia de la API, el cliente permitido, los scopes delegados y el app role que se exigen, identidades estables de tenant más objeto, restricciones de fila parametrizadas y un rol de base de datos restringido. La elección del AND, la audiencia exacta y el predicado del registro tendrían que quedar a la vista de quien revisa, sin que tenga que adivinar.' }, { en: 'Write the acceptance rule so a denied example is easy to construct.', es: 'Escribí la regla de aceptación de modo que sea fácil armar un ejemplo rechazado.' }),
    F({ en: 'Name the residual risks', es: 'Nombrá los riesgos que quedan' }, { en: 'The improved design still trusts the API process, tenant administrators, identity-provider behavior, database operators and the frontend supply chain. The fixture does not test Conditional Access, tenant assignment propagation, production TLS, key rotation outages or a real deployment. A high-quality review names those dependencies and assigns evidence work rather than declaring the system universally secure.', es: 'El diseño mejorado igual confía en el proceso de la API, en los administradores del tenant, en el comportamiento del proveedor de identidad, en los operadores de la base de datos y en la cadena de suministro del frontend. El fixture no prueba Conditional Access, la propagación de asignaciones en el tenant, el TLS de producción, las caídas durante una rotación de claves ni un despliegue real. Una buena revisión nombra esas dependencias y asigna trabajo de evidencia, en lugar de declarar que el sistema es seguro en todos los casos.' }, { en: 'Precision about limits is part of a defensible design.', es: 'La precisión sobre los límites es parte de un diseño defendible.' })
  ], { en: 'Find a case where sign-in succeeds but the correct final result is denial.', es: 'Encontrá un caso donde el inicio de sesión sale bien pero el resultado final correcto es un rechazo.' }, [
    Q({ en: 'Which counterexample defeats accept any Microsoft-signed JWT?', es: '¿Qué contraejemplo derrota a aceptar cualquier JWT firmado por Microsoft?' }, [{ en: 'A valid Graph token presented to this API', es: 'Un token válido de Graph presentado a esta API' }, { en: 'A successful own-record read', es: 'Una lectura exitosa de un registro propio' }, { en: 'An exact API audience', es: 'Una audiencia exacta de la API' }], 0, { en: 'A trusted signer can issue tokens for many recipients. Recipient binding still matters.', es: 'Un firmante de confianza puede emitir tokens para muchos destinatarios. Atar el token a su destinatario sigue importando.' }),
    Q({ en: 'Which proposal erases a business boundary?', es: '¿Qué propuesta borra un límite de negocio?' }, [{ en: 'Restricted runtime database role', es: 'Rol de base de datos de ejecución restringido' }, { en: 'Validated tenant-plus-object identity', es: 'Identidad validada de tenant más objeto' }, { en: 'Approving any row whenever Approver is present', es: 'Aprobar cualquier fila siempre que esté Approver' }], 2, { en: 'The role alone omits tenant, ownership and state requirements.', es: 'El rol, solo, deja afuera los requisitos de tenant, propiedad y estado.' }),
    Q({ en: 'What does a good review say about untested production behavior?', es: '¿Qué dice una buena revisión sobre el comportamiento de producción que no se probó?' }, [{ en: 'Assume the framework handles it', es: 'Que se supone que lo maneja el framework' }, { en: 'Name the dependency and required evidence', es: 'Que nombra la dependencia y la evidencia que hace falta' }, { en: 'Mark it passed if local tests passed', es: 'Que se marca como aprobado si pasaron las pruebas locales' }], 1, { en: 'The reviewer should distinguish implemented checks from external guarantees.', es: 'Quien revisa tiene que distinguir las verificaciones implementadas de las garantías externas.' })
  ], [
    S({ en: 'Threat-model the proposal', es: 'Modelá las amenazas de la propuesta' }, { en: 'Use the weak proposal in scene one. Draw a malicious browser, a valid token for another audience, an ordinary user and an administrator.', es: 'Usá la propuesta débil de la escena uno. Dibujá un navegador malicioso, un token válido para otra audiencia, un usuario común y un administrador.' }, { en: 'At least five concrete failure paths with the enforcing component missing.', es: 'Al menos cinco caminos de falla concretos, con el componente que debería hacer cumplir la regla ausente.' }),
    S({ en: 'Run one counterexample', es: 'Ejecutá un contraejemplo' }, { en: 'Use the fixture audience and ownership scenarios to replace two theoretical objections with observed denials in the corrected sample.', es: 'Usá los escenarios de audiencia y de propiedad del fixture para reemplazar dos objeciones teóricas por rechazos observados en el ejemplo corregido.' }, { en: 'Wrong audience remains 401; another owner remains 404.', es: 'La audiencia equivocada sigue dando 401; otro dueño sigue dando 404.' }, 'node lab.mjs audience'),
    S({ en: 'Write the acceptance rule', es: 'Escribí la regla de aceptación' }, { en: 'Express read and approve separately. Include caller type, resource audience, scope, role where required, tenant, ownership relation and mutable state.', es: 'Expresá la lectura y la aprobación por separado. Incluí el tipo de quien llama, la audiencia del recurso, el scope, el rol donde se exige, el tenant, la relación de propiedad y el estado que cambia.' }, { en: 'A reviewer can derive a positive and negative test from each condition.', es: 'Quien revisa puede sacar una prueba positiva y una negativa de cada condición.' }),
    S({ en: 'Write the risk register', es: 'Escribí el registro de riesgos' }, { en: 'Use CAPSTONE.md. Prioritize tenant verification, deployment transport, secrets, monitoring and role-removal latency.', es: 'Usá CAPSTONE.md. Priorizá la verificación en el tenant, el transporte del despliegue, los secretos, el monitoreo y la demora al quitar un rol.' }, { en: 'Each unverified dependency has an owner, evidence to collect and an acceptance condition.', es: 'Cada dependencia sin verificar tiene un responsable, la evidencia que hay que juntar y una condición de aceptación.' })
  ], 'security-review');

  add(6, 'capstone', { en: 'Capstone: defend one request', es: 'Trabajo final: defendé un pedido' }, { en: 'Deliver an explanation that survives a skeptical review.', es: 'Entregá una explicación que resista una revisión escéptica.' }, 'boundaries', [
    F({ en: 'Trace the successful path', es: 'Seguí el camino exitoso' }, { en: 'Draw Alice, Angular, Entra, Spring and PostgreSQL. Label every network hop with the principal, credential or message, recipient and decision. For an own-record read, connect the access token\'s validated identity to the SQL predicate and resulting row. For approval, explain why the actor must be an approver and must not own the pending request.', es: 'Dibujá a Alice, Angular, Entra, Spring y PostgreSQL. Etiquetá cada salto de red con el principal, la credencial o el mensaje, el destinatario y la decisión. Para la lectura de un registro propio, conectá la identidad validada del access token con el predicado SQL y la fila que resulta. Para la aprobación, explicá por qué quien actúa tiene que ser aprobador y no puede ser el dueño de la solicitud pendiente.' }, { en: 'Every arrow must name both its evidence and its receiver.', es: 'Cada flecha tiene que nombrar su evidencia y su receptor.' }),
    F({ en: 'Defend the denied paths', es: 'Defendé los caminos rechazados' }, { en: 'Present a wrong audience, forged signature, expired credential, missing scope, missing role, wrong owner, wrong tenant and concurrent approval. Predict each result and show the corresponding observed output. Then remove a hypothetical control on paper and state which test would catch the regression. Do not earn credit merely by reproducing the helper\'s PASS lines.', es: 'Presentá una audiencia equivocada, una firma falsificada, una credencial vencida, un scope que falta, un rol que falta, el dueño equivocado, el tenant equivocado y una aprobación concurrente. Predecí cada resultado y mostrá la salida observada que le corresponde. Después quitá en papel un control hipotético y decí qué prueba detectaría la regresión. Reproducir las líneas PASS del ayudante no alcanza para sumar puntos.' }, { en: 'A test is useful when you can explain which mistake it detects.', es: 'Una prueba sirve cuando podés explicar qué error detecta.' }),
    F({ en: 'Separate readiness from completion', es: 'Separá estar listo de haber terminado' }, { en: 'Run the local suite and review the source. If you have a tenant, attach the sanitized tenant evidence worksheet; otherwise label those criteria unverified. Propose the production work still required: protected hosting, TLS, secret management, monitored validation failures, identity lifecycle and a tested operational response. Finishing the course demonstrates reasoning and local evidence, not production certification.', es: 'Ejecutá la suite local y revisá el código. Si tenés un tenant, adjuntá la planilla de evidencia del tenant saneada; si no, marcá esos criterios como sin verificar. Proponé el trabajo de producción que todavía hace falta: hosting protegido, TLS, manejo de secretos, fallas de validación monitoreadas, ciclo de vida de las identidades y una respuesta operativa probada. Terminar el curso demuestra razonamiento y evidencia local, no una certificación de producción.' }, { en: 'The final deliverable is a justified security contract with honest evidence.', es: 'La entrega final es un contrato de seguridad justificado, con evidencia honesta.' })
  ], { en: 'Choose any denial. Explain it without naming a command, then locate the enforcing code.', es: 'Elegí cualquier rechazo. Explicalo sin nombrar un comando, y después ubicá el código que lo hace cumplir.' }, [
    Q({ en: 'What is the strongest capstone artifact?', es: '¿Cuál es la entrega más sólida del trabajo final?' }, [{ en: 'A terminal screenshot alone', es: 'Una captura de la terminal, sola' }, { en: 'A traced policy with positive and negative evidence and stated limits', es: 'Una política seguida paso a paso, con evidencia positiva y negativa y límites declarados' }, { en: 'A list of memorized commands', es: 'Una lista de comandos memorizados' }], 1, { en: 'The deliverable connects architecture, implementation and observation.', es: 'La entrega conecta la arquitectura, la implementación y la observación.' }),
    Q({ en: 'A tenant activity was not run. How should it be recorded?', es: 'Una actividad del tenant no se ejecutó. ¿Cómo se anota?' }, [{ en: 'Unverified, with the local alternative clearly labeled', es: 'Sin verificar, con la alternativa local indicada claramente' }, { en: 'Passed because the fixture resembles Entra', es: 'Aprobada, porque el fixture se parece a Entra' }, { en: 'Omitted from the evidence', es: 'Se deja fuera de la evidencia' }], 0, { en: 'Accurate evidence includes what has not been established.', es: 'La evidencia precisa incluye lo que no se estableció.' }),
    Q({ en: 'Which statement can the local suite support?', es: '¿Qué afirmación puede sostener la suite local?' }, [{ en: 'This production deployment is certified secure', es: 'Este despliegue de producción está certificado como seguro' }, { en: 'The tenant enforces every desired sign-in policy', es: 'El tenant aplica todas las políticas de inicio de sesión deseadas' }, { en: 'These specific API and database checks passed against fixture credentials', es: 'Estas verificaciones concretas de la API y de la base de datos pasaron con credenciales del fixture' }], 2, { en: 'The scope of the evidence is the executed local system and its explicit assertions.', es: 'El alcance de la evidencia es el sistema local ejecutado y sus aserciones explícitas.' })
  ], [
    S({ en: 'Submit the architecture first', es: 'Entregá primero la arquitectura' }, { en: 'Use CAPSTONE.md and WORKSHEET.txt. Predict all denial cases before executing the suite.', es: 'Usá CAPSTONE.md y WORKSHEET.txt. Predecí todos los casos de rechazo antes de ejecutar la suite.' }, { en: 'A request diagram, policy matrix and predictions for every negative case.', es: 'Un diagrama del pedido, una matriz de políticas y predicciones para cada caso negativo.' }),
    S({ en: 'Collect the local evidence', es: 'Juntá la evidencia local' }, { en: 'The suite runs real API and SQL checks, restores the approval fixture and leaves the three services running. It refuses Entra mode.', es: 'La suite ejecuta verificaciones reales de la API y de SQL, restaura el fixture de aprobación y deja corriendo los tres servicios. Se niega a correr en modo Entra.' }, { en: '50 assertions pass. The evidence file is labs/runs/all.json.', es: 'Pasan 50 aserciones. El archivo de evidencia es labs/runs/all.json.' }, 'node lab.mjs all'),
    S({ en: 'Attach tenant evidence separately', es: 'Adjuntá la evidencia del tenant por separado' }, { en: 'Use TENANT-EVIDENCE.txt. State whether the real registration, consent, sign-in and role paths were executed.', es: 'Usá TENANT-EVIDENCE.txt. Indicá si se ejecutaron los caminos reales de registro, consentimiento, inicio de sesión y rol.' }, { en: 'Sanitized observed results or explicit NOT EXECUTED entries.', es: 'Resultados observados y saneados, o entradas NOT EXECUTED explícitas.' }),
    S({ en: 'Defend the residual risk', es: 'Defendé el riesgo que queda' }, { en: 'Use the rubric to explain a compromised browser, compromised API, a removed role with an existing token and an identity-provider outage. Stop the lab when finished with docker compose stop.', es: 'Usá la rúbrica para explicar un navegador comprometido, una API comprometida, un rol quitado con un token existente y una caída del proveedor de identidad. Cuando termines, detené el lab con docker compose stop.' }, { en: 'A reviewer can see the guarantee, its assumptions and the next validation needed.', es: 'Quien revisa puede ver la garantía, sus supuestos y la próxima validación que hace falta.' })
  ], 'security-review');

  return { version: '1.4.0', date: '2026-10-29', angular: '21.2.25', msal: '5.27.0', spring: '4.1.2', postgres: '18.6', units, lessons };
})();
